fn native_agent_relative_time(updated_at_ms: i64) -> String {
    if updated_at_ms <= 0 {
        return "Unknown time".to_owned();
    }
    let now_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis().min(i64::MAX as u128) as i64)
        .unwrap_or(updated_at_ms);
    let age_seconds = now_ms.saturating_sub(updated_at_ms) / 1_000;
    match age_seconds {
        0..=59 => "Just now".to_owned(),
        60..=3_599 => format!("{}m ago", age_seconds / 60),
        3_600..=86_399 => format!("{}h ago", age_seconds / 3_600),
        86_400..=2_591_999 => format!("{}d ago", age_seconds / 86_400),
        _ => format!("{}mo ago", age_seconds / 2_592_000),
    }
}

const NATIVE_LOCAL_SHELL_ACTIVITY_WRAPPER: &str = r#"
monitor_script=$1
shift
sh -c "$monitor_script" craic-terminal-monitor "$$" &
exec "$@"
"#;
const NATIVE_LOCAL_SHELL_ACTIVITY_MONITOR: &str = r#"
root_pid=$1
monitor_pid=$$
last_state=

sleep 0.1
while kill -0 "$root_pid" 2>/dev/null; do
    child_pid="$(pgrep -P "$root_pid" 2>/dev/null | awk -v monitor="$monitor_pid" '$1 != monitor { print $1; exit }')"
    if [ -n "$child_pid" ]; then
        state=active
    else
        state=idle
    fi
    if [ "$state" != "$last_state" ]; then
        printf '\033]0;craic-terminal-activity:%s\007' "$state" > /dev/tty
        last_state=$state
    fi
    sleep 0.5
done
"#;
