    fn schedule_workspace_file_save(&self) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        if files.loaded_text_path.borrow().is_none() || !files.text_editable.get() {
            return;
        }
        files.text_dirty.set(true);
        let generation = files.text_edit_generation.get().wrapping_add(1);
        files.text_edit_generation.set(generation);
        files
            .metadata
            .setToolTip(Some(&NSString::from_str("Unsaved changes")));
        self.set_workspace_file_editor_status(Some("Edited"));
        let delegate = MainThreadBound::new(self.retain(), self.mtm());
        let when = DispatchTime::try_from(Duration::from_millis(90))
            .expect("90 milliseconds fits dispatch time");
        let _ = DispatchQueue::main().after(when, move || {
            let Some(mtm) = MainThreadMarker::new() else {
                return;
            };
            let delegate = delegate.get(mtm);
            let Some(files) = delegate.ivars().files.get() else {
                return;
            };
            if files.text_edit_generation.get() == generation && files.text_dirty.get() {
                delegate.request_workspace_text_highlights();
                delegate.flush_workspace_file_save();
            }
        });
    }

    fn request_workspace_text_highlights(&self) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        let Some(workspace_id) = self.ivars().active_workspace_id.borrow().clone() else {
            return;
        };
        let Some(path) = files.loaded_text_path.borrow().clone() else {
            return;
        };
        let Some(cancellation) = self.workspace_cancellation_token() else {
            return;
        };
        let Some(requests) = self.ivars().repository_requests.get() else {
            return;
        };
        let Some(access) = self
            .ivars()
            .workspace_handle
            .borrow()
            .as_ref()
            .map(|handle| handle.workspace_files())
        else {
            return;
        };
        let text = files.text_buffer.borrow().clone();
        let selection = files.text_selection.get();
        let completion_cursor_utf16 = (selection.length == 0).then_some(selection.location);
        let completion_cursor =
            completion_cursor_utf16.and_then(|offset| byte_offset_for_utf16_offset(&text, offset));
        if let Err(error) = requests.try_send(RepositoryRequest::HighlightWorkspaceText {
            workspace_id,
            access,
            path,
            text,
            completion_cursor,
            completion_cursor_utf16,
            edit_generation: files.text_edit_generation.get(),
            cancellation,
        }) {
            log::debug!("native Files syntax request coalesced error={error}");
        }
    }

    fn flush_workspace_file_save(&self) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        if !files.text_dirty.get() || files.text_save_in_progress.get() {
            return;
        }
        let Some(path) = files.loaded_text_path.borrow().clone() else {
            return;
        };
        let Some(expected_signature) = files.loaded_text_signature.borrow().clone() else {
            return;
        };
        let Some(access) = self
            .ivars()
            .workspace_handle
            .borrow()
            .as_ref()
            .map(|handle| handle.workspace_files())
        else {
            return;
        };
        self.request_workspace_file_save_with_retry(
            access,
            path,
            files.text_buffer.borrow().clone(),
            expected_signature,
            files.text_edit_generation.get(),
            true,
        );
    }

    fn request_workspace_file_save_with_retry(
        &self,
        access: Arc<dyn FileAccess>,
        path: FileNodePath,
        text: String,
        expected_signature: FileSignature,
        edit_generation: u64,
        allow_sudo_retry: bool,
    ) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        if files.text_save_in_progress.replace(true) {
            return;
        }
        let Some(workspace_id) = self.ivars().active_workspace_id.borrow().clone() else {
            files.text_save_in_progress.set(false);
            return;
        };
        let Some(cancellation) = self.workspace_cancellation_token() else {
            files.text_save_in_progress.set(false);
            return;
        };
        self.set_workspace_file_editor_status(Some("Saving…"));
        self.set_page_badge("files", NativePageBadge::Indicator);
        let Some(requests) = self.ivars().repository_requests.get() else {
            self.finish_workspace_file_save(
                &workspace_id,
                access,
                path,
                text,
                expected_signature,
                edit_generation,
                allow_sudo_retry,
                Err("The repository service is unavailable.".to_string()),
            );
            return;
        };
        let completion_access = access.clone();
        let completion_path = path.clone();
        let completion_text = text.clone();
        let completion_signature = expected_signature.clone();
        if let Err(error) = requests.try_send(RepositoryRequest::SaveWorkspaceFile {
            workspace_id: workspace_id.clone(),
            access,
            path,
            text,
            expected_signature,
            edit_generation,
            allow_sudo_retry,
            cancellation,
        }) {
            self.finish_workspace_file_save(
                &workspace_id,
                completion_access,
                completion_path,
                completion_text,
                completion_signature,
                edit_generation,
                allow_sudo_retry,
                Err(format!("Unable to queue file save: {error}")),
            );
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn finish_workspace_file_save(
        &self,
        workspace_id: &str,
        access: Arc<dyn FileAccess>,
        path: FileNodePath,
        text: String,
        expected_signature: FileSignature,
        edit_generation: u64,
        allow_sudo_retry: bool,
        result: Result<FileNodeInfo, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        self.set_page_badge("files", NativePageBadge::None);
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        files.text_save_in_progress.set(false);
        match result {
            Ok(info) => {
                if files.loaded_text_path.borrow().as_ref() == Some(&path) {
                    files
                        .loaded_text_signature
                        .replace(Some(file_signature_from_info(&info)));
                    if files.text_edit_generation.get() == edit_generation {
                        files.text_dirty.set(false);
                        files
                            .metadata
                            .setToolTip(Some(&NSString::from_str("Saved")));
                        self.set_workspace_file_editor_status(Some("Saved"));
                        if let Some(next_path) = files.pending_text_selection.borrow_mut().take()
                            && let Some(next_row) = self
                                .filtered_file_tree_rows()
                                .iter()
                                .position(|candidate| candidate.info.path == next_path)
                        {
                            files.table.selectRowIndexes_byExtendingSelection(
                                &NSIndexSet::indexSetWithIndex(next_row),
                                false,
                            );
                            files.table.scrollRowToVisible(next_row as isize);
                        }
                    } else {
                        self.flush_workspace_file_save();
                    }
                }
                log::debug!(
                    "native Files text saved workspace={} path={} generation={}",
                    workspace_id,
                    path.display(),
                    edit_generation
                );
            }
            Err(error) => {
                if allow_sudo_retry && permission_denied_message(&error) {
                    self.offer_file_sudo_retry(
                        access,
                        NativeSudoRetry::Save {
                            path,
                            text,
                            expected_signature,
                            edit_generation,
                        },
                        "Save Failed",
                        &error,
                    );
                    return;
                }
                files.text_dirty.set(true);
                files.pending_text_selection.borrow_mut().take();
                files
                    .metadata
                    .setToolTip(Some(&NSString::from_str("Save failed")));
                self.set_workspace_file_editor_status(Some("Save failed"));
                self.present_path_action_error("Save Failed", &error);
                log::warn!(
                    "native Files text save failed workspace={workspace_id} path={}: {error}",
                    path.display()
                );
            }
        }
    }

    fn apply_workspace_folder(
        &self,
        workspace_id: &str,
        path: &FileNodePath,
        request_id: u64,
        result: Result<NativeFolderPreview, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        if files.preview_request_id.get() != request_id
            || files.selected_path.borrow().as_ref() != Some(path)
        {
            log::debug!(
                "discarding stale workspace folder preview workspace={workspace_id} path={}",
                path.display()
            );
            return;
        }
        if files.editor_search_visible.get() {
            self.hide_editor_search();
        }
        unsafe { files.preview_spinner.stopAnimation(None) };
        files.preview_spinner.setHidden(true);
        files.preview_scroll.setHidden(true);
        files.preview_code.setHidden(true);
        files.preview_image.setHidden(true);
        files.preview_image.clear_image();
        files.preview_pdf.setHidden(true);
        unsafe { files.preview_pdf.setDocument(None) };
        files.preview_web_mode.set(NativeWebPreviewMode::Hidden);
        files.preview_web.setHidden(true);
        files.preview_divider.setHidden(true);
        unsafe { files.preview_web.stopLoading() };
        self.clear_csv_table_preview();

        match result {
            Ok(preview) => {
                let path_label = if path.display().is_empty() {
                    "Workspace root".to_string()
                } else {
                    path.display()
                };
                let permissions = preview.info.mode.map_or_else(
                    || "Unknown".to_string(),
                    |mode| {
                        let mut symbolic = String::with_capacity(10);
                        symbolic.push(if preview.info.capabilities.listable {
                            'd'
                        } else {
                            '-'
                        });
                        for (mask, character) in [
                            (0o400, 'r'),
                            (0o200, 'w'),
                            (0o100, 'x'),
                            (0o040, 'r'),
                            (0o020, 'w'),
                            (0o010, 'x'),
                            (0o004, 'r'),
                            (0o002, 'w'),
                            (0o001, 'x'),
                        ] {
                            symbolic.push(if mode & mask == mask { character } else { '-' });
                        }
                        format!("{symbolic} ({:04o})", mode & 0o777)
                    },
                );
                let modified = preview.info.modified.map_or_else(
                    || "Unknown".to_string(),
                    |modified| {
                        let seconds = modified.duration_since(std::time::UNIX_EPOCH).map_or_else(
                            |error| -error.duration().as_secs_f64(),
                            |duration| duration.as_secs_f64(),
                        );
                        let date = NSDate::dateWithTimeIntervalSince1970(seconds);
                        NSDateFormatter::localizedStringFromDate_dateStyle_timeStyle(
                            &date,
                            NSDateFormatterStyle::MediumStyle,
                            NSDateFormatterStyle::ShortStyle,
                        )
                        .to_string()
                    },
                );
                let rows = vec![
                    vec!["Workspace Path".to_string(), path_label],
                    vec!["Location".to_string(), preview.provider_path],
                    vec!["Files".to_string(), preview.file_count.to_string()],
                    vec!["Folders".to_string(), preview.folder_count.to_string()],
                    vec![
                        "Total Items".to_string(),
                        (preview.file_count + preview.folder_count).to_string(),
                    ],
                    vec![
                        "Owner".to_string(),
                        preview.info.owner.unwrap_or_else(|| "Unknown".to_string()),
                    ],
                    vec![
                        "Group".to_string(),
                        preview.info.group.unwrap_or_else(|| "Unknown".to_string()),
                    ],
                    vec!["Permissions".to_string(), permissions],
                    vec![
                        "Size".to_string(),
                        preview.info.len.map_or_else(
                            || "Unknown".to_string(),
                            |bytes| format!("{bytes} bytes"),
                        ),
                    ],
                    vec!["Last Modified".to_string(), modified],
                ];
                let content_width = files.preview_table_scroll.contentSize().width.max(320.0);
                for (index, (title, width)) in
                    [("Property", 170.0), ("Value", content_width - 170.0)]
                        .into_iter()
                        .enumerate()
                {
                    let column = NSTableColumn::initWithIdentifier(
                        NSTableColumn::alloc(self.mtm()),
                        &NSUserInterfaceItemIdentifier::from_str(&format!("folder.{index}")),
                    );
                    column.setTitle(&NSString::from_str(title));
                    column.setWidth(width.max(120.0));
                    column.setMinWidth(100.0);
                    files.preview_table.addTableColumn(&column);
                }
                files
                    .preview_table_columns
                    .replace(vec!["Property".to_string(), "Value".to_string()]);
                files.preview_table_rows.replace(rows);
                files.preview_table.setFrameSize(NSSize::new(
                    content_width,
                    (files.preview_table_rows.borrow().len() as f64 * 27.0)
                        .max(files.preview_table_scroll.contentSize().height),
                ));
                files.preview_table.reloadData();
                files
                    .preview_table_scroll
                    .setBorderType(NSBorderType::NoBorder);
                files.preview_table_scroll.setHidden(false);
                files.empty.setHidden(true);
                self.set_workspace_file_editor_status(Some(&format!(
                    "{} files · {} folders",
                    preview.file_count, preview.folder_count
                )));
            }
            Err(error) => {
                files.empty.setStringValue(&NSString::from_str(&format!(
                    "Unable to load folder details: {error}"
                )));
                files.empty.setHidden(false);
            }
        }
    }

    fn clear_font_preview(&self) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        if files.font_registration.borrow().is_some() {
            files.suppress_text_change.set(true);
            files.preview_text.setString(&NSString::new());
            files.suppress_text_change.set(false);
            files
                .preview_text
                .setFont(Some(&NSFont::monospacedSystemFontOfSize_weight(12.0, 0.0)));
            files
                .preview_text
                .setTextContainerInset(NSSize::new(10.0, 10.0));
            files.font_registration.borrow_mut().take();
        }
    }

    fn apply_font_preview(&self, bytes: &[u8]) -> Result<String, String> {
        let Some(files) = self.ivars().files.get() else {
            return Err("The Files preview is unavailable.".to_string());
        };
        let length = isize::try_from(bytes.len())
            .map_err(|_| "This font is too large for Core Graphics.".to_string())?;
        // SAFETY: CFData copies the valid byte slice before this function returns.
        let data = unsafe { CFData::new(None, bytes.as_ptr(), length) }
            .ok_or_else(|| "macOS could not create font data.".to_string())?;
        // SAFETY: Core Text receives immutable CFData containing the complete font bytes.
        let descriptor = unsafe { CTFontManagerCreateFontDescriptorFromData(&data) }
            .ok_or_else(|| "macOS could not decode this font.".to_string())?;
        // SAFETY: Core Text receives the same valid immutable font data.
        let descriptors = unsafe { CTFontManagerCreateFontDescriptorsFromData(&data) };
        if descriptors.count() == 0 {
            return Err("macOS could not find a font face in this file.".to_string());
        }
        // SAFETY: This CFArray was produced by Core Text and contains font descriptors.
        unsafe {
            CTFontManagerRegisterFontDescriptors(
                &descriptors,
                CTFontManagerScope::Process,
                true,
                None,
            );
        }
        let registration = NativeFontRegistration { descriptors };
        // SAFETY: The descriptor is valid and a null matrix requests the identity transform.
        let font = unsafe { CTFont::with_font_descriptor(&descriptor, 12.0, std::ptr::null()) };
        let post_script_name = unsafe { font.post_script_name() }.to_string();
        let display_name = unsafe { font.full_name() }.to_string();

        let mut content = String::new();
        let mut ranges = Vec::new();
        let mut append_line = |text: &str, size: f64| {
            let start = content.encode_utf16().count();
            content.push_str(text);
            let length = content.encode_utf16().count() - start;
            ranges.push((NSRange::new(start, length), size));
            content.push('\n');
        };
        append_line(&display_name, 30.0);
        append_line("", 14.0);
        append_line("abcdefghijklmnopqrstuvwxyz", 26.0);
        append_line("ABCDEFGHIJKLMNOPQRSTUVWXYZ", 26.0);
        append_line("0123456789 .:,;(*!?')", 26.0);
        append_line("", 14.0);
        for size in [12.0, 18.0, 24.0, 36.0, 48.0, 72.0, 96.0] {
            append_line("Sphinx of black quartz, judge my vow.", size);
        }

        files.suppress_text_change.set(true);
        files.preview_text.setString(&NSString::from_str(&content));
        files.suppress_text_change.set(false);
        let Some(storage) = (unsafe { files.preview_text.textStorage() }) else {
            return Err("macOS could not create font preview storage.".to_string());
        };
        let font_attribute = unsafe { NSFontAttributeName };
        storage.beginEditing();
        for (range, size) in ranges {
            let Some(preview_font) =
                NSFont::fontWithName_size(&NSString::from_str(&post_script_name), size)
            else {
                storage.endEditing();
                return Err(format!("macOS could not activate {display_name}."));
            };
            unsafe { storage.addAttribute_value_range(font_attribute, &preview_font, range) };
        }
        storage.endEditing();
        files.preview_text.setEditable(false);
        files.preview_text.setContinuousSpellCheckingEnabled(false);
        files
            .preview_text
            .setTextContainerInset(NSSize::new(24.0, 24.0));
        files.preview_scroll.setHidden(false);
        files.empty.setHidden(true);
        files.font_registration.replace(Some(registration));
        self.layout_files_preview();
        Ok(display_name)
    }

    fn apply_workspace_file(
        &self,
        workspace_id: &str,
        path: &FileNodePath,
        request_id: u64,
        result: Result<FileRead, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        if files.preview_request_id.get() != request_id
            || files.selected_path.borrow().as_ref() != Some(path)
        {
            log::debug!(
                "discarding stale workspace file preview workspace={workspace_id} path={} request_id={} current_request_id={} selected_path={:?}",
                path.display(),
                request_id,
                files.preview_request_id.get(),
                files
                    .selected_path
                    .borrow()
                    .as_ref()
                    .map(FileNodePath::display)
            );
            return;
        }
        if files.editor_search_visible.get() {
            self.hide_editor_search();
        }
        unsafe { files.preview_spinner.stopAnimation(None) };
        files.preview_spinner.setHidden(true);
        files.preview_scroll.setHidden(true);
        files.preview_code.setHidden(true);
        files.preview_image.setHidden(true);
        files.preview_image.clear_image();
        files.preview_pdf.setHidden(true);
        // SAFETY: Preview completions are applied on AppKit's main thread.
        unsafe { files.preview_pdf.setDocument(None) };
        self.clear_csv_table_preview();
        files.preview_web_mode.set(NativeWebPreviewMode::Hidden);
        files.preview_web.setHidden(true);
        files.preview_divider.setHidden(true);
        // SAFETY: Preview completions are applied on AppKit's main thread.
        unsafe { files.preview_web.stopLoading() };
        self.clear_font_preview();
        self.clear_sqlite_preview();
        files.loaded_text_path.borrow_mut().take();
        files.loaded_text_signature.borrow_mut().take();
        files.text_buffer.borrow_mut().clear();
        files.text_selection.set(NSRange::new(0, 0));
        files.text_editable.set(false);
        files.preview_code.clear_completions();
        files.text_dirty.set(false);
        files.preview_text.setEditable(false);
        match result {
            Ok(read) => {
                let info = read.info;
                let Some(bytes) = read.bytes else {
                    let limit = if is_font_preview_path(&path.display()) {
                        FONT_CONTENT_PREVIEW_LIMIT
                    } else {
                        FILE_CONTENT_PREVIEW_LIMIT
                    };
                    files.empty.setStringValue(&NSString::from_str(&format!(
                        "Preview unavailable because this file exceeds {} MiB.",
                        limit / (1024 * 1024)
                    )));
                    files.empty.setHidden(false);
                    return;
                };
                let path_display = path.display();
                if has_sqlite_header(&bytes) {
                    self.request_workspace_sqlite(path.clone(), info, Some(bytes));
                    return;
                }
                let is_safetensors = Path::new(&path_display)
                    .extension()
                    .and_then(|extension| extension.to_str())
                    .is_some_and(|extension| extension.eq_ignore_ascii_case("safetensors"));
                if is_safetensors {
                    match metadata_text_from_bytes(&bytes, &path_display) {
                        Ok(metadata) => {
                            files.suppress_text_change.set(true);
                            files.preview_text.setString(&NSString::from_str(&metadata));
                            files.suppress_text_change.set(false);
                            files.preview_text.setEditable(false);
                            files.preview_text.setContinuousSpellCheckingEnabled(false);
                            files.preview_scroll.setHidden(false);
                            files.empty.setHidden(true);
                            self.set_workspace_file_editor_status(Some("Safetensors metadata"));
                            self.layout_files_preview();
                        }
                        Err(error) => {
                            files.suppress_text_change.set(true);
                            files.preview_text.setString(&NSString::new());
                            files.suppress_text_change.set(false);
                            files.empty.setStringValue(&NSString::from_str(&error));
                            files.empty.setHidden(false);
                        }
                    }
                    return;
                }
                if is_font_preview_path(&path_display) {
                    match self.apply_font_preview(&bytes) {
                        Ok(name) => {
                            log::info!(
                                "native Core Text font preview applied path={path_display} name={name} bytes={}",
                                bytes.len()
                            );
                            self.set_workspace_file_editor_status(Some(&format!("Font · {name}")));
                        }
                        Err(error) => {
                            files.suppress_text_change.set(true);
                            files.preview_text.setString(&NSString::new());
                            files.suppress_text_change.set(false);
                            files.empty.setStringValue(&NSString::from_str(&error));
                            files.empty.setHidden(false);
                        }
                    }
                    return;
                }
                if is_image_preview_path(&path_display) {
                    let data = NSData::with_bytes(&bytes);
                    if let Some(image) = NSImage::initWithData(NSImage::alloc(), &data) {
                        files.preview_image.set_image(&image);
                        files.preview_image.setHidden(false);
                        files.empty.setHidden(true);
                    } else {
                        files.empty.setStringValue(&NSString::from_str(
                            "The image could not be decoded by macOS.",
                        ));
                        files.empty.setHidden(false);
                    }
                    return;
                }
                if is_pdf_preview_path(&path_display) {
                    let data = NSData::with_bytes(&bytes);
                    // SAFETY: PDFKit parses retained immutable NSData on AppKit's main thread and
                    // PDFView retains the resulting document.
                    if let Some(document) =
                        unsafe { PDFDocument::initWithData(PDFDocument::alloc(), &data) }
                    {
                        unsafe { files.preview_pdf.setDocument(Some(&document)) };
                        files.preview_pdf.setHidden(false);
                        files.empty.setHidden(true);
                    } else {
                        files.empty.setStringValue(&NSString::from_str(
                            "macOS could not decode this PDF.",
                        ));
                        files.empty.setHidden(false);
                    }
                    return;
                }
                if let Some(mime) = media_preview_mime(&path_display) {
                    let data = NSData::with_bytes(&bytes);
                    let Some(base_url) = NSURL::URLWithString(&NSString::from_str("about:blank"))
                    else {
                        files.empty.setStringValue(&NSString::from_str(
                            "Unable to initialize the media preview.",
                        ));
                        files.empty.setHidden(false);
                        return;
                    };
                    // SAFETY: WebKit copies or retains all arguments, and this completion is
                    // applied on AppKit's main thread.
                    unsafe {
                        files
                            .preview_web
                            .loadData_MIMEType_characterEncodingName_baseURL(
                                &data,
                                &NSString::from_str(mime),
                                &NSString::from_str("utf-8"),
                                &base_url,
                            )
                    };
                    files.preview_web_mode.set(NativeWebPreviewMode::FullPane);
                    self.layout_files_preview();
                    files.empty.setHidden(true);
                    return;
                }
                if bytes.contains(&0) {
                    files.empty.setStringValue(&NSString::from_str(
                        "A native preview is not available for this binary file.",
                    ));
                    files.empty.setHidden(false);
                    return;
                }
                match String::from_utf8(bytes) {
                    Ok(text) => {
                        files.loaded_text_path.replace(Some(path.clone()));
                        files
                            .loaded_text_signature
                            .replace(Some(file_signature_from_info(&info)));
                        files.text_dirty.set(false);
                        files.text_buffer.replace(text.clone());
                        files.text_editable.set(info.capabilities.writable);
                        let pending_selection = self
                            .ivars()
                            .pending_files_path
                            .borrow()
                            .as_deref()
                            .filter(|pending| *pending == path.display())
                            .and_then(|_| self.ivars().pending_files_line.get())
                            .map(|line| {
                                let utf16 = utf16_offset_for_line_column(
                                    &text,
                                    line,
                                    self.ivars().pending_files_column.get().unwrap_or(1),
                                );
                                let byte = byte_offset_for_utf16_offset(&text, utf16).unwrap_or(0);
                                (NSRange::new(utf16, 0), byte)
                            });
                        let (selection, selection_byte) =
                            pending_selection.unwrap_or((NSRange::new(0, 0), 0));
                        files.text_selection.set(selection);
                        files.preview_code.set_document(
                            &path_display,
                            text.clone(),
                            Vec::new(),
                            craic_render_skia::EditorSelection {
                                anchor: selection_byte,
                                focus: selection_byte,
                            },
                            info.capabilities.writable,
                            true,
                        );
                        files.preview_scroll.setHidden(true);
                        files.preview_code.setHidden(false);
                        files.empty.setHidden(true);
                        self.request_workspace_text_highlights();
                    }
                    Err(_) => {
                        files.empty.setStringValue(&NSString::from_str(
                            "This file is not valid UTF-8 text.",
                        ));
                        files.empty.setHidden(false);
                    }
                }
            }
            Err(error) => {
                files.empty.setStringValue(&NSString::from_str(&format!(
                    "Unable to preview file: {error}"
                )));
                files.empty.setHidden(false);
                log::warn!(
                    "native workspace file preview failed workspace={workspace_id} path={}: {error}",
                    path.display()
                );
            }
        }
    }

    fn set_workspace_file_editor_status(&self, status: Option<&str>) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        let base = files.metadata_base.borrow();
        let value = status
            .filter(|status| !status.is_empty())
            .map_or_else(|| base.clone(), |status| format!("{base} · {status}"));
        files.metadata.setStringValue(&NSString::from_str(&value));
    }

    fn apply_workspace_text_highlights(
        &self,
        workspace_id: &str,
        path: &FileNodePath,
        edit_generation: u64,
        result: Result<NativeTextAnalysis, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        if files.loaded_text_path.borrow().as_ref() != Some(path)
            || files.text_edit_generation.get() != edit_generation
        {
            return;
        }
        let analysis = match result {
            Ok(analysis) => analysis,
            Err(error) => {
                log::debug!(
                    "native Files syntax unavailable path={} error={error}",
                    path.display()
                );
                return;
            }
        };
        let text = files.text_buffer.borrow().clone();
        files.preview_code.set_syntax(analysis.syntax.clone());
        files.preview_code.set_folds(analysis.fold_ranges.clone());
        files
            .preview_code
            .set_diagnostics(analysis.diagnostics.clone());
        files.preview_code.clear_completions();
        if analysis.markdown_lint.is_empty() {
            files.preview_code.setToolTip(None);
        } else {
            let mut rules = analysis
                .markdown_lint
                .iter()
                .filter_map(|issue| issue.rule_name.as_deref())
                .take(4)
                .collect::<Vec<_>>();
            rules.sort_unstable();
            rules.dedup();
            let detail = if rules.is_empty() {
                format!("{} Markdown lint issue(s)", analysis.markdown_lint.len())
            } else {
                format!(
                    "{} Markdown lint issue(s): {}",
                    analysis.markdown_lint.len(),
                    rules.join(", ")
                )
            };
            files
                .preview_code
                .setToolTip(Some(&NSString::from_str(&detail)));
        }
        if let (Some(completion), Some(expected_cursor)) =
            (analysis.completion, analysis.completion_cursor_utf16)
        {
            let selection = files.text_selection.get();
            if selection.length == 0
                && selection.location == expected_cursor
                && let Some(replacement_range) = utf16_range_for_byte_range(
                    &text,
                    completion.replacement_start,
                    completion.replacement_end,
                )
                && replacement_range.location + replacement_range.length == expected_cursor
            {
                files.preview_code.set_completions(
                    completion
                        .items
                        .into_iter()
                        .map(|item| item.insert_text)
                        .collect(),
                    replacement_range,
                );
            }
        }
        if let Some(result) = analysis.csv_table {
            self.apply_csv_table_preview(result);
            return;
        }
        if let Some(result) = analysis.web_preview {
            let preview = match result {
                Ok(preview) => preview,
                Err(error) => {
                    files.preview_scroll.setHidden(true);
                    files.preview_code.setHidden(true);
                    files.preview_web_mode.set(NativeWebPreviewMode::Hidden);
                    files.preview_web.setHidden(true);
                    files.preview_divider.setHidden(true);
                    files.empty.setStringValue(&NSString::from_str(&error));
                    files.empty.setHidden(false);
                    self.layout_files_preview();
                    return;
                }
            };
            let base_url = self
                .ivars()
                .workspace_handle
                .borrow()
                .as_ref()
                .and_then(|handle| handle.workspace_files().local_path(path))
                .and_then(|path| path.parent().map(Path::to_path_buf))
                .map(|path| {
                    NSURL::fileURLWithPath_isDirectory(
                        &NSString::from_str(&path.to_string_lossy()),
                        true,
                    )
                });
            files
                .markdown_editor_source_offset
                .set(self.current_files_editor_source_offset());
            unsafe {
                files.preview_web.loadHTMLString_baseURL(
                    &NSString::from_str(&preview.html),
                    base_url.as_deref(),
                );
            }
            files.preview_web_mode.set(preview.mode);
            if preview.mode == NativeWebPreviewMode::FullPane {
                files.preview_scroll.setHidden(true);
                files.preview_code.setHidden(true);
                files.preview_text.setEditable(false);
            } else {
                files.preview_scroll.setHidden(true);
                files.preview_code.setHidden(false);
            }
            files.empty.setHidden(true);
        } else {
            files.preview_web_mode.set(NativeWebPreviewMode::Hidden);
        }
        self.layout_files_preview();
    }

    fn clear_csv_table_preview(&self) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        files.preview_table_scroll.setHidden(true);
        files.preview_table_rows.borrow_mut().clear();
        files.preview_table_columns.borrow_mut().clear();
        // NSTableView exposes a live NSArray here. Snapshot its retained members before removing
        // them; mutating the table while objc2 is enumerating that array aborts the process.
        let columns = files
            .preview_table
            .tableColumns()
            .iter()
            .collect::<Vec<_>>();
        for column in columns {
            files.preview_table.removeTableColumn(&column);
        }
        files.preview_table.reloadData();
    }

    fn clear_sqlite_preview(&self) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        files
            .sqlite_generation
            .set(files.sqlite_generation.get().wrapping_add(1));
        files.sqlite_state.borrow_mut().take();
        files.sqlite_controls.setHidden(true);
        files.sqlite_table_selector.removeAllItems();
        files.sqlite_column_selector.removeAllItems();
        files.sqlite_filter.setStringValue(&NSString::new());
        files.sqlite_previous.setEnabled(false);
        files.sqlite_next.setEnabled(false);
        files.sqlite_reload.setEnabled(false);
        files
            .sqlite_status
            .setStringValue(&NSString::from_str("Page –"));
    }

    fn request_workspace_sqlite_page(&self) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        let Some(workspace_id) = self.ivars().active_workspace_id.borrow().clone() else {
            return;
        };
        let Some(path) = files.selected_path.borrow().clone() else {
            return;
        };
        let Some(cancellation) = self.workspace_cancellation_token() else {
            return;
        };
        let Some((db_path, table, page, filter_column, filter, sort)) =
            files.sqlite_state.borrow().as_ref().and_then(|state| {
                state
                    .tables
                    .get(state.selected_table)
                    .cloned()
                    .map(|table| {
                        (
                            state.db_path.clone(),
                            table,
                            state.page,
                            state.filter_column,
                            state.filter.clone(),
                            state.sort.clone(),
                        )
                    })
            })
        else {
            return;
        };
        let generation = files.sqlite_generation.get().wrapping_add(1);
        files.sqlite_generation.set(generation);
        files.sqlite_previous.setEnabled(false);
        files.sqlite_next.setEnabled(false);
        files
            .sqlite_status
            .setStringValue(&NSString::from_str("Loading…"));
        files.preview_spinner.setHidden(false);
        unsafe { files.preview_spinner.startAnimation(None) };
        let Some(requests) = self.ivars().repository_requests.get() else {
            return;
        };
        if let Err(error) = requests.try_send(RepositoryRequest::LoadWorkspaceSqlitePage {
            workspace_id,
            path,
            db_path,
            table,
            page,
            filter_column,
            filter,
            sort,
            generation,
            cancellation,
        }) {
            unsafe { files.preview_spinner.stopAnimation(None) };
            files.preview_spinner.setHidden(true);
            files
                .sqlite_status
                .setStringValue(&NSString::from_str("Load failed"));
            files.empty.setStringValue(&NSString::from_str(&format!(
                "Unable to queue SQLite rows: {error}"
            )));
            files.empty.setHidden(false);
        }
    }

    fn apply_workspace_sqlite_schema(
        &self,
        workspace_id: &str,
        path: &FileNodePath,
        request_id: u64,
        result: Result<NativeSqliteSchema, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        if files.preview_request_id.get() != request_id
            || files.selected_path.borrow().as_ref() != Some(path)
        {
            log::debug!(
                "discarding stale SQLite schema workspace={workspace_id} path={} request_id={request_id}",
                path.display()
            );
            return;
        }
        unsafe { files.preview_spinner.stopAnimation(None) };
        files.preview_spinner.setHidden(true);
        files.preview_scroll.setHidden(true);
        files.preview_image.setHidden(true);
        files.preview_image.clear_image();
        files.preview_pdf.setHidden(true);
        unsafe { files.preview_pdf.setDocument(None) };
        files.preview_web_mode.set(NativeWebPreviewMode::Hidden);
        files.preview_web.setHidden(true);
        files.preview_divider.setHidden(true);
        unsafe { files.preview_web.stopLoading() };
        self.clear_csv_table_preview();

        match result {
            Ok(schema) if schema.tables.is_empty() => {
                files
                    .empty
                    .setStringValue(&NSString::from_str("This database has no tables or views."));
                files.empty.setHidden(false);
            }
            Ok(schema) => {
                for table in &schema.tables {
                    let suffix = if table.kind == "view" { " (view)" } else { "" };
                    files
                        .sqlite_table_selector
                        .addItemWithTitle(&NSString::from_str(&format!("{}{suffix}", table.name)));
                }
                files
                    .sqlite_column_selector
                    .addItemWithTitle(&NSString::from_str("All columns"));
                files.sqlite_state.replace(Some(NativeSqliteState {
                    db_path: schema.db_path,
                    _materialized: schema.materialized,
                    tables: schema.tables,
                    selected_table: 0,
                    columns: Vec::new(),
                    page: 0,
                    total_rows: 0,
                    filter: String::new(),
                    filter_column: None,
                    sort: None,
                }));
                files.sqlite_controls.setHidden(false);
                files.sqlite_reload.setEnabled(true);
                files.empty.setHidden(true);
                self.layout_files_preview();
                self.request_workspace_sqlite_page();
            }
            Err(error) => {
                files.empty.setStringValue(&NSString::from_str(&format!(
                    "Unable to preview SQLite database: {error}"
                )));
                files.empty.setHidden(false);
                log::warn!(
                    "native SQLite schema failed workspace={workspace_id} path={}: {error}",
                    path.display()
                );
            }
        }
    }

    fn apply_workspace_sqlite_page(
        &self,
        workspace_id: &str,
        path: &FileNodePath,
        generation: u64,
        result: Result<sqlite_preview::Page, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        if files.sqlite_generation.get() != generation
            || files.selected_path.borrow().as_ref() != Some(path)
        {
            return;
        }
        unsafe { files.preview_spinner.stopAnimation(None) };
        files.preview_spinner.setHidden(true);
        self.clear_csv_table_preview();
        files
            .preview_table_scroll
            .setBorderType(NSBorderType::BezelBorder);
        match result {
            Ok(page) => {
                let selected_table_matches = files
                    .sqlite_state
                    .borrow()
                    .as_ref()
                    .and_then(|state| state.tables.get(state.selected_table))
                    == Some(&page.table);
                if !selected_table_matches {
                    return;
                }
                if let Some(state) = files.sqlite_state.borrow_mut().as_mut() {
                    state.columns = page.columns.clone();
                    state.page = page.page;
                    state.total_rows = page.total_rows;
                    if state
                        .filter_column
                        .is_some_and(|index| index >= state.columns.len())
                    {
                        state.filter_column = None;
                    }
                }
                let (selected_filter_column, active_sort) = files
                    .sqlite_state
                    .borrow()
                    .as_ref()
                    .map(|state| (state.filter_column, state.sort.clone()))
                    .unwrap_or((None, None));
                for (index, column) in page.columns.iter().enumerate() {
                    let table_column = NSTableColumn::initWithIdentifier(
                        NSTableColumn::alloc(self.mtm()),
                        &NSUserInterfaceItemIdentifier::from_str(&format!("sqlite.{index}")),
                    );
                    table_column.setTitle(&NSString::from_str(&column.name));
                    table_column.setWidth(160.0);
                    table_column.setMinWidth(80.0);
                    table_column.setMaxWidth(420.0);
                    files.preview_table.addTableColumn(&table_column);
                    if let Some(sort) = active_sort.as_ref()
                        && sort.column_index == index
                    {
                        let symbol = match sort.direction {
                            NativeSqliteSortDirection::Ascending => "chevron.up",
                            NativeSqliteSortDirection::Descending => "chevron.down",
                        };
                        let indicator = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                            &NSString::from_str(symbol),
                            Some(&NSString::from_str("SQLite sort direction")),
                        );
                        files
                            .preview_table
                            .setIndicatorImage_inTableColumn(indicator.as_deref(), &table_column);
                    }
                }
                files.preview_table_columns.replace(
                    page.columns
                        .iter()
                        .map(|column| column.name.clone())
                        .collect(),
                );
                files.preview_table_rows.replace(page.rows);
                let content_size = files.preview_table_scroll.contentSize();
                files.preview_table.setFrameSize(NSSize::new(
                    (files.preview_table_columns.borrow().len() as f64 * 160.0)
                        .max(content_size.width),
                    (files.preview_table_rows.borrow().len() as f64 * 27.0)
                        .max(content_size.height),
                ));
                files.preview_table.reloadData();
                files.sqlite_column_selector.removeAllItems();
                files
                    .sqlite_column_selector
                    .addItemWithTitle(&NSString::from_str("All columns"));
                for column in &page.columns {
                    files
                        .sqlite_column_selector
                        .addItemWithTitle(&NSString::from_str(&column.name));
                }
                files
                    .sqlite_column_selector
                    .selectItemAtIndex(
                        selected_filter_column.map_or(0, |index| index + 1) as isize,
                    );
                let first = if page.total_rows == 0 {
                    0
                } else {
                    page.page * sqlite_preview::PAGE_SIZE + 1
                };
                let last =
                    page.page * sqlite_preview::PAGE_SIZE + files.preview_table_rows.borrow().len();
                files
                    .sqlite_status
                    .setStringValue(&NSString::from_str(&format!(
                        "{first}–{last} of {}",
                        page.total_rows
                    )));
                files.sqlite_previous.setEnabled(page.page > 0);
                files.sqlite_next.setEnabled(last < page.total_rows);
                files.preview_table_scroll.setHidden(false);
                files.empty.setHidden(true);
                self.set_workspace_file_editor_status(Some(&format!(
                    "{} · rows {first}–{last} of {}",
                    page.table.name, page.total_rows
                )));
                self.layout_files_preview();
                log::debug!(
                    "native SQLite rows applied path={} table={} page={} rows={} total={}",
                    path.display(),
                    page.table.name,
                    page.page + 1,
                    files.preview_table_rows.borrow().len(),
                    page.total_rows
                );
            }
            Err(error) => {
                files.sqlite_previous.setEnabled(false);
                files.sqlite_next.setEnabled(false);
                files
                    .sqlite_status
                    .setStringValue(&NSString::from_str("Load failed"));
                files.empty.setStringValue(&NSString::from_str(&format!(
                    "Unable to load SQLite rows: {error}"
                )));
                files.empty.setHidden(false);
                log::warn!("native SQLite rows failed path={}: {error}", path.display());
            }
        }
    }

    fn apply_csv_table_preview(&self, result: Result<Option<CsvTable>, String>) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        self.clear_csv_table_preview();
        files
            .preview_table_scroll
            .setBorderType(NSBorderType::BezelBorder);
        files.preview_scroll.setHidden(true);
        files.preview_web_mode.set(NativeWebPreviewMode::Hidden);
        files.preview_web.setHidden(true);
        files.preview_divider.setHidden(true);
        match result {
            Ok(Some(table)) => {
                let visible_rows = table.rows.len();
                let status = if table.total_rows > visible_rows {
                    format!(
                        "{} columns · showing first {} of {} rows",
                        table.columns.len(),
                        visible_rows,
                        table.total_rows
                    )
                } else {
                    format!(
                        "{} columns · {} rows",
                        table.columns.len(),
                        table.total_rows
                    )
                };
                for (index, title) in table.columns.iter().enumerate() {
                    let column = NSTableColumn::initWithIdentifier(
                        NSTableColumn::alloc(self.mtm()),
                        &NSUserInterfaceItemIdentifier::from_str(&format!("csv.{index}")),
                    );
                    column.setTitle(&NSString::from_str(title));
                    column.setWidth(160.0);
                    column.setMinWidth(80.0);
                    column.setMaxWidth(360.0);
                    files.preview_table.addTableColumn(&column);
                }
                files.preview_table_columns.replace(table.columns);
                files.preview_table_rows.replace(table.rows);
                let content_size = files.preview_table_scroll.contentSize();
                files.preview_table.setFrameSize(NSSize::new(
                    (files.preview_table_columns.borrow().len() as f64 * 160.0)
                        .max(content_size.width),
                    (files.preview_table_rows.borrow().len() as f64 * 27.0)
                        .max(content_size.height),
                ));
                files.preview_table.reloadData();
                files.preview_table_scroll.setHidden(false);
                files.empty.setHidden(true);
                self.set_workspace_file_editor_status(Some(&status));
            }
            Ok(None) => {
                files
                    .empty
                    .setStringValue(&NSString::from_str("This CSV file is empty."));
                files.empty.setHidden(false);
            }
            Err(error) => {
                files.empty.setStringValue(&NSString::from_str(&error));
                files.empty.setHidden(false);
                log::warn!("native CSV table preview parse failed: {error}");
            }
        }
        self.layout_files_preview();
    }

    fn toggle_file_tree_row(&self, row: usize) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        let Some(row_data) = self.filtered_file_tree_rows().get(row).cloned() else {
            return;
        };
        if !row_data.info.capabilities.listable {
            return;
        }
        let mut expanded = files.expanded.borrow_mut();
        if !expanded.remove(&row_data.info.path) {
            expanded.insert(row_data.info.path);
        }
        drop(expanded);
        self.request_files_tree();
    }

    fn request_files_tree(&self) {
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        let Some(workspace_id) = self.ivars().active_workspace_id.borrow().clone() else {
            return;
        };
        let Some(handle) = self.ivars().workspace_handle.borrow().clone() else {
            return;
        };
        let Some(cancellation) = self.workspace_cancellation_token() else {
            return;
        };
        if files.rows.borrow().is_empty()
            && let Some(path) = self.ivars().pending_files_path.borrow().clone()
        {
            let root = handle.workspace_files().root();
            let target = root.join_child(path);
            files.selected_path.replace(Some(target.clone()));
            let mut parent = target.parent();
            while let Some(path) = parent {
                if path.is_root() {
                    break;
                }
                files.expanded.borrow_mut().insert(path.clone());
                parent = path.parent();
            }
        }
        let generation = files.generation.get().wrapping_add(1);
        files.generation.set(generation);
        files.loading.set(true);
        self.set_page_badge("files", NativePageBadge::Indicator);
        files.dirty.set(false);
        files.status.setHidden(false);
        files
            .status
            .setStringValue(&NSString::from_str("Loading workspace files…"));
        files.spinner.setHidden(false);
        unsafe { files.spinner.startAnimation(None) };
        let Some(requests) = self.ivars().repository_requests.get() else {
            return;
        };
        if let Err(error) = requests.try_send(RepositoryRequest::LoadFilesTree {
            workspace_id,
            handle,
            expanded: files.expanded.borrow().clone(),
            generation,
            cancellation,
        }) {
            files.loading.set(false);
            unsafe { files.spinner.stopAnimation(None) };
            files.spinner.setHidden(true);
            files.status.setStringValue(&NSString::from_str(&format!(
                "Unable to queue file loading: {error}"
            )));
            self.set_page_badge("files", NativePageBadge::None);
        }
    }

    fn subscribe_files_monitor(&self, workspace_id: &str) {
        self.ivars().files_monitor.borrow_mut().take();
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        let Some(handle) = self.ivars().workspace_handle.borrow().clone() else {
            return;
        };
        let Some(completions) = self.ivars().frontend_completions.get().cloned() else {
            return;
        };
        let access = handle.workspace_files();
        let mut watched = HashSet::from([access.root()]);
        watched.extend(files.expanded.borrow().iter().cloned());
        if let Some(selected) = files.selected_path.borrow().clone() {
            watched.insert(selected);
        }
        let watched_workspace = workspace_id.to_string();
        let callback_workspace = watched_workspace.clone();
        match access.watch(FileWatchRequest {
            paths: watched.into_iter().collect(),
        }) {
            Ok((subscription, receiver)) => {
                self.ivars()
                    .files_monitor
                    .replace(Some(NativeFileMonitor::new(
                        subscription,
                        receiver,
                        callback_workspace,
                        completions,
                    )));
                log::debug!("native Files watch subscribed workspace={watched_workspace}");
            }
            Err(error) => {
                log::warn!("native Files watch unavailable workspace={watched_workspace}: {error}");
            }
        }
    }

    fn workspace_files_changed(&self, workspace_id: &str) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        files.dirty.set(true);
        if self.is_active_page("files") && !files.loading.get() {
            log::debug!("native Files watch refreshing workspace={workspace_id}");
            self.request_files_tree();
        }
    }

    fn apply_files_tree(
        &self,
        workspace_id: &str,
        generation: u64,
        result: Result<Vec<NativeFileRow>, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        let Some(files) = self.ivars().files.get() else {
            return;
        };
        if files.generation.get() != generation {
            return;
        }
        files.loading.set(false);
        self.set_page_badge("files", NativePageBadge::None);
        unsafe { files.spinner.stopAnimation(None) };
        files.spinner.setHidden(true);
        match result {
            Ok(rows) => {
                files.rows.replace(rows);
                files.status.setHidden(!files.rows.borrow().is_empty());
                if files.rows.borrow().is_empty() {
                    files
                        .status
                        .setStringValue(&NSString::from_str("This workspace is empty."));
                }
            }
            Err(error) => {
                files.rows.borrow_mut().clear();
                files.status.setHidden(false);
                files.status.setStringValue(&NSString::from_str(&error));
                log::warn!("native Files tree failed workspace={workspace_id}: {error}");
            }
        }
        files.table.reloadData();
        // AppKit delivers the selection callback synchronously from selectRowIndexes:. Copy the
        // retained path before selecting so that callback can update selected_path re-entrantly.
        let selected_path = files.selected_path.borrow().clone();
        if let Some(selected) = selected_path
            && let Some(row) = self
                .filtered_file_tree_rows()
                .iter()
                .position(|candidate| candidate.info.path == selected)
        {
            let selection_changed = files.table.selectedRow() != row as isize;
            files
                .table
                .selectRowIndexes_byExtendingSelection(&NSIndexSet::indexSetWithIndex(row), false);
            files.table.scrollRowToVisible(row as isize);
            if !selection_changed {
                self.select_file_tree_row(row);
            }
        }
        self.subscribe_files_monitor(workspace_id);
        if files.dirty.get() && !files.loading.get() {
            self.request_files_tree();
        }
    }

    fn show_commit_author_picker(&self, sender: &NSButton) {
        let Some(workspace_id) = self.ivars().active_workspace_id.borrow().clone() else {
            return;
        };
        let Some(handle) = self.ivars().git_handle.borrow().clone() else {
            return;
        };
        let popover = self.commit_author_picker();
        if popover.isShown() {
            popover.close();
            return;
        }

        self.ivars()
            .author_options
            .replace(github::cached_commit_email_options().unwrap_or_default());
        self.ivars().author_loading.set(true);
        self.ivars().author_error.borrow_mut().take();
        log::debug!(
            "native commit author picker opened cached_options={}",
            self.ivars().author_options.borrow().len()
        );
        popover.showRelativeToRect_ofView_preferredEdge(sender.bounds(), sender, NSRectEdge::MaxX);
        self.refresh_commit_author_results();

        let Some(requests) = self.ivars().repository_requests.get() else {
            self.apply_commit_author_options(
                &workspace_id,
                Err("Repository service is unavailable.".to_string()),
            );
            return;
        };
        if let Err(error) = requests.try_send(RepositoryRequest::LoadCommitAuthors {
            workspace_id: workspace_id.clone(),
            handle,
        }) {
            self.apply_commit_author_options(
                &workspace_id,
                Err(format!("Unable to queue GitHub email loading: {error}")),
            );
        }
    }

    fn commit_author_picker(&self) -> Retained<NSPopover> {
        if let Some(popover) = self.ivars().author_popover.get() {
            return popover.clone();
        }

        let root = NSView::initWithFrame(
            NSView::alloc(self.mtm()),
            NSRect::new(
                NSPoint::new(0.0, 0.0),
                NSSize::new(AUTHOR_PICKER_WIDTH, AUTHOR_PICKER_HEIGHT),
            ),
        );
        let table = NSTableView::initWithFrame(
            NSTableView::alloc(self.mtm()),
            NSRect::new(
                NSPoint::new(0.0, 0.0),
                NSSize::new(AUTHOR_PICKER_WIDTH - 24.0, AUTHOR_PICKER_HEIGHT - 24.0),
            ),
        );
        let column = NSTableColumn::initWithIdentifier(
            NSTableColumn::alloc(self.mtm()),
            &NSUserInterfaceItemIdentifier::from_str("commit.author"),
        );
        column.setWidth(AUTHOR_PICKER_WIDTH - 24.0);
        table.addTableColumn(&column);
        table.setHeaderView(None);
        table.setColumnAutoresizingStyle(
            NSTableViewColumnAutoresizingStyle::LastColumnOnlyAutoresizingStyle,
        );
        table.setRowHeight(AUTHOR_ROW_HEIGHT);
        table.setIntercellSpacing(NSSize::new(0.0, 2.0));
        table.setStyle(NSTableViewStyle::Inset);
        table.setUsesAlternatingRowBackgroundColors(false);
        table.setAllowsEmptySelection(true);
        table.setAllowsMultipleSelection(false);
        table.setBackgroundColor(&NSColor::clearColor());
        unsafe {
            table.setDataSource(Some(ProtocolObject::from_ref(self)));
            table.setDelegate(Some(ProtocolObject::from_ref(self)));
        }
        let scroll = NSScrollView::initWithFrame(
            NSScrollView::alloc(self.mtm()),
            NSRect::new(
                NSPoint::new(0.0, 0.0),
                NSSize::new(AUTHOR_PICKER_WIDTH - 24.0, AUTHOR_PICKER_HEIGHT - 24.0),
            ),
        );
        scroll.setFrameOrigin(NSPoint::new(12.0, 12.0));
        scroll.setBorderType(NSBorderType::NoBorder);
        scroll.setDrawsBackground(false);
        scroll.setAutomaticallyAdjustsContentInsets(true);
        scroll.setHasVerticalScroller(true);
        scroll.setHasHorizontalScroller(false);
        scroll.setAutohidesScrollers(true);
        scroll.setDocumentView(Some(&table));
        scroll.setAutoresizingMask(
            NSAutoresizingMaskOptions::ViewWidthSizable
                | NSAutoresizingMaskOptions::ViewHeightSizable,
        );
        root.addSubview(&scroll);

        let controller = NSViewController::new(self.mtm());
        controller.setView(&root);
        controller.setPreferredContentSize(NSSize::new(AUTHOR_PICKER_WIDTH, AUTHOR_PICKER_HEIGHT));
        let popover = NSPopover::new(self.mtm());
        popover.setBehavior(NSPopoverBehavior::Transient);
        popover.setContentSize(NSSize::new(AUTHOR_PICKER_WIDTH, AUTHOR_PICKER_HEIGHT));
        popover.setContentViewController(Some(&controller));

        self.ivars()
            .author_table
            .set(table)
            .expect("commit author table is initialized once");
        self.ivars()
            .author_popover
            .set(popover.clone())
            .expect("commit author popover is initialized once");
        popover
    }

    fn refresh_commit_author_results(&self) {
        let Some(table) = self.ivars().author_table.get() else {
            return;
        };
        self.ivars().author_selection_suppressed.set(true);
        table.reloadData();
        let current = self
            .ivars()
            .repository_snapshot
            .borrow()
            .as_ref()
            .and_then(|snapshot| snapshot.user_email.as_deref())
            .and_then(|email| {
                self.ivars()
                    .author_options
                    .borrow()
                    .iter()
                    .position(|option| option.email.eq_ignore_ascii_case(email))
            });
        log::debug!(
            "native commit author picker refreshed options={} loading={} error={} current_row={current:?}",
            self.ivars().author_options.borrow().len(),
            self.ivars().author_loading.get(),
            self.ivars().author_error.borrow().is_some(),
        );
        if let Some(row) = current {
            table.selectRowIndexes_byExtendingSelection(&NSIndexSet::indexSetWithIndex(row), false);
            table.scrollRowToVisible(row as isize);
        } else {
            // SAFETY: The table and delegate are owned by this AppKit main-thread object.
            unsafe { table.deselectAll(None) };
        }
        table.layoutSubtreeIfNeeded();
        self.ivars().author_selection_suppressed.set(false);
    }

    fn make_commit_author_cell(&self, table: &NSTableView, row: usize) -> Option<Retained<NSView>> {
        let width = table.bounds().size.width.max(AUTHOR_PICKER_WIDTH - 24.0);
        let option = self.ivars().author_options.borrow().get(row).cloned();
        let Some(option) = option else {
            let cell = NSView::initWithFrame(
                NSView::alloc(self.mtm()),
                NSRect::new(
                    NSPoint::new(0.0, 0.0),
                    NSSize::new(width, AUTHOR_ROW_HEIGHT),
                ),
            );
            let loading = self.ivars().author_loading.get();
            let error = self.ivars().author_error.borrow().clone();
            if loading {
                let spinner = NSProgressIndicator::initWithFrame(
                    NSProgressIndicator::alloc(self.mtm()),
                    NSRect::new(NSPoint::new(12.0, 18.0), NSSize::new(16.0, 16.0)),
                );
                spinner.setStyle(NSProgressIndicatorStyle::Spinning);
                spinner.setControlSize(NSControlSize::Small);
                spinner.setIndeterminate(true);
                spinner.setDisplayedWhenStopped(false);
                // SAFETY: The table creates and animates this indicator on AppKit's main thread.
                unsafe { spinner.startAnimation(None) };
                cell.addSubview(&spinner);
            }
            let (heading, detail) = if loading {
                ("Loading GitHub accounts…", None)
            } else if let Some(error) = error.as_deref() {
                ("Couldn’t load GitHub accounts", Some(error))
            } else {
                (
                    "No GitHub accounts found",
                    Some("Sign in with the GitHub CLI to add one."),
                )
            };
            let heading = NSTextField::labelWithString(&NSString::from_str(heading), self.mtm());
            heading.setFrame(NSRect::new(
                NSPoint::new(if loading { 38.0 } else { 12.0 }, 26.0),
                NSSize::new(width - if loading { 50.0 } else { 24.0 }, 18.0),
            ));
            heading.setFont(Some(&NSFont::systemFontOfSize(12.0)));
            heading.setLineBreakMode(NSLineBreakMode::ByTruncatingTail);
            cell.addSubview(&heading);
            if let Some(detail) = detail {
                let subtitle =
                    NSTextField::labelWithString(&NSString::from_str(detail), self.mtm());
                subtitle.setFrame(NSRect::new(
                    NSPoint::new(12.0, 7.0),
                    NSSize::new(width - 24.0, 17.0),
                ));
                subtitle.setFont(Some(&NSFont::systemFontOfSize(10.5)));
                subtitle.setTextColor(Some(&NSColor::secondaryLabelColor()));
                subtitle.setLineBreakMode(NSLineBreakMode::ByTruncatingTail);
                subtitle.setToolTip(Some(&NSString::from_str(detail)));
                cell.addSubview(&subtitle);
            }
            return Some(cell);
        };

        let display_name = option.name.trim();
        let primary = if display_name.is_empty() {
            option.email.as_str()
        } else {
            display_name
        };
        let is_current = self
            .ivars()
            .repository_snapshot
            .borrow()
            .as_ref()
            .and_then(|snapshot| snapshot.user_email.as_deref())
            .is_some_and(|email| email.eq_ignore_ascii_case(&option.email));
        let text_width = width - if is_current { 104.0 } else { 68.0 };
        let avatar_source = option
            .avatar_url
            .as_ref()
            .map(|url| (format!("url:{url}"), AvatarSource::Url(url.to_string())));
        let avatar_image = avatar_source
            .as_ref()
            .and_then(|(key, _)| self.ivars().avatar_images.borrow().get(key).cloned())
            .or_else(|| {
                NSImage::imageWithSystemSymbolName_accessibilityDescription(
                    &NSString::from_str("person.crop.circle.fill"),
                    Some(&NSString::from_str(primary)),
                )
            });
        let cell = NSView::initWithFrame(
            NSView::alloc(self.mtm()),
            NSRect::new(
                NSPoint::new(0.0, 0.0),
                NSSize::new(width, AUTHOR_ROW_HEIGHT),
            ),
        );
        if let Some(image) = avatar_image {
            let avatar = NSImageView::imageViewWithImage(&image, self.mtm());
            avatar.setFrame(NSRect::new(
                NSPoint::new(12.0, 11.0),
                NSSize::new(30.0, 30.0),
            ));
            avatar.setImageScaling(NSImageScaling::ScaleProportionallyUpOrDown);
            avatar.setWantsLayer(true);
            if let Some(layer) = avatar.layer() {
                layer.setCornerRadius(15.0);
                layer.setMasksToBounds(true);
            }
            cell.addSubview(&avatar);
        }

        let title = NSTextField::labelWithString(&NSString::from_str(primary), self.mtm());
        title.setFrame(NSRect::new(
            NSPoint::new(52.0, if display_name.is_empty() { 17.0 } else { 27.0 }),
            NSSize::new(text_width.max(1.0), 18.0),
        ));
        title.setAutoresizingMask(NSAutoresizingMaskOptions::ViewWidthSizable);
        title.setFont(Some(&NSFont::systemFontOfSize(12.5)));
        title.setLineBreakMode(NSLineBreakMode::ByTruncatingTail);
        cell.addSubview(&title);

        if !display_name.is_empty() {
            let subtitle =
                NSTextField::labelWithString(&NSString::from_str(&option.email), self.mtm());
            subtitle.setFrame(NSRect::new(
                NSPoint::new(52.0, 8.0),
                NSSize::new(text_width.max(1.0), 17.0),
            ));
            subtitle.setAutoresizingMask(NSAutoresizingMaskOptions::ViewWidthSizable);
            subtitle.setFont(Some(&NSFont::systemFontOfSize(10.5)));
            subtitle.setTextColor(Some(&NSColor::secondaryLabelColor()));
            subtitle.setLineBreakMode(NSLineBreakMode::ByTruncatingMiddle);
            subtitle.setToolTip(Some(&NSString::from_str(&option.email)));
            cell.addSubview(&subtitle);
        }

        if is_current {
            if let Some(image) = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                &NSString::from_str("checkmark.circle.fill"),
                Some(&NSString::from_str("Current commit author")),
            ) {
                let current = NSImageView::imageViewWithImage(&image, self.mtm());
                current.setFrame(NSRect::new(
                    NSPoint::new(width - 34.0, 16.0),
                    NSSize::new(20.0, 20.0),
                ));
                current.setAutoresizingMask(NSAutoresizingMaskOptions::ViewMinXMargin);
                current.setContentTintColor(Some(&NSColor::controlAccentColor()));
                current.setToolTip(Some(&NSString::from_str("Current commit author")));
                cell.addSubview(&current);
            }
        }
        cell.setToolTip(Some(&NSString::from_str(&format!(
            "Use {primary} <{}>",
            option.email
        ))));
        if let Some((cache_key, source)) = avatar_source
            && !self.ivars().avatar_images.borrow().contains_key(&cache_key)
        {
            self.request_avatar(cache_key, source);
        }
        Some(cell)
    }

    fn apply_commit_author_options(
        &self,
        workspace_id: &str,
        result: Result<Vec<CommitEmailOption>, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        self.ivars().author_loading.set(false);
        match result {
            Ok(options) => {
                log::debug!(
                    "native commit author options loaded workspace={workspace_id} count={}",
                    options.len()
                );
                self.ivars().author_options.replace(options);
                self.ivars().author_error.borrow_mut().take();
            }
            Err(error) => {
                log::warn!("native commit author options failed: {error}");
                self.ivars().author_error.replace(Some(error));
            }
        }
        self.refresh_commit_author_results();
    }

    fn finish_commit_author(
        &self,
        workspace_id: &str,
        handle: Arc<GitRepoHandle>,
        result: Result<WorkspaceSnapshot, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        match result {
            Ok(snapshot) => {
                if let Some(popover) = self.ivars().author_popover.get() {
                    popover.close();
                }
                self.apply_repository_snapshot(workspace_id, Some(handle), Ok(snapshot));
                log::info!("native commit author updated workspace={workspace_id}");
            }
            Err(error) => {
                self.present_path_action_error("Author Selection Failed", &error);
                log::warn!("native commit author update failed workspace={workspace_id}: {error}");
            }
        }
    }

    fn show_branch_picker(&self, sender: &NSButton) {
        let popover = self.branch_picker();
        if popover.isShown() {
            popover.close();
            return;
        }
        self.ivars().branch_merge_mode.set(false);
        if let Some(search) = self.ivars().branch_search.get() {
            search.setStringValue(&NSString::new());
            search.setPlaceholderString(Some(&NSString::from_str("Search branches")));
        }
        self.update_branch_footer();
        self.refresh_branch_results("");
        popover.showRelativeToRect_ofView_preferredEdge(sender.bounds(), sender, NSRectEdge::MinY);
        if let Some(search) = self.ivars().branch_search.get()
            && let Some(window) = search.window()
        {
            window.makeFirstResponder(Some(search));
        }
    }

    fn branch_picker(&self) -> Retained<NSPopover> {
        if let Some(popover) = self.ivars().branch_popover.get() {
            return popover.clone();
        }

        let mtm = self.mtm();
        let root = NSView::initWithFrame(
            NSView::alloc(mtm),
            NSRect::new(
                NSPoint::new(0.0, 0.0),
                NSSize::new(BRANCH_PICKER_WIDTH, BRANCH_PICKER_HEIGHT),
            ),
        );
        let search = NSSearchField::new(mtm);
        search.setFrame(NSRect::new(
            NSPoint::new(12.0, BRANCH_PICKER_HEIGHT - 44.0),
            NSSize::new(BRANCH_PICKER_WIDTH - 62.0, 32.0),
        ));
        search.setPlaceholderString(Some(&NSString::from_str("Search branches")));
        search.setSendsSearchStringImmediately(true);
        unsafe {
            search.setTarget(Some(self));
            search.setAction(Some(sel!(filterBranches:)));
        }
        root.addSubview(&search);

        let add = unsafe {
            NSButton::buttonWithImage_target_action(
                &NSImage::imageWithSystemSymbolName_accessibilityDescription(
                    &NSString::from_str("plus"),
                    Some(&NSString::from_str("New branch")),
                )
                .expect("macOS 14 provides the plus SF Symbol"),
                Some(self),
                Some(sel!(addBranch:)),
                mtm,
            )
        };
        add.setFrame(NSRect::new(
            NSPoint::new(BRANCH_PICKER_WIDTH - 44.0, BRANCH_PICKER_HEIGHT - 44.0),
            NSSize::new(32.0, 32.0),
        ));
        add.setBezelStyle(NSBezelStyle::Circular);
        add.setControlSize(NSControlSize::Regular);
        add.setToolTip(Some(&NSString::from_str("New branch")));
        root.addSubview(&add);

        let list = NSView::initWithFrame(
            NSView::alloc(mtm),
            NSRect::new(
                NSPoint::new(0.0, 0.0),
                NSSize::new(BRANCH_PICKER_WIDTH - 24.0, BRANCH_PICKER_HEIGHT - 108.0),
            ),
        );
        let scroll = NSScrollView::initWithFrame(
            NSScrollView::alloc(mtm),
            NSRect::new(
                NSPoint::new(12.0, 56.0),
                NSSize::new(BRANCH_PICKER_WIDTH - 24.0, BRANCH_PICKER_HEIGHT - 108.0),
            ),
        );
        scroll.setBorderType(NSBorderType::NoBorder);
        scroll.setDrawsBackground(false);
        scroll.setHasVerticalScroller(true);
        scroll.setAutohidesScrollers(true);
        scroll.setDocumentView(Some(&list));
        root.addSubview(&scroll);

        let footer_image = NSImage::imageWithSystemSymbolName_accessibilityDescription(
            &NSString::from_str("arrow.triangle.merge"),
            Some(&NSString::from_str("Merge branch")),
        )
        .or_else(|| {
            NSImage::imageWithSystemSymbolName_accessibilityDescription(
                &NSString::from_str("arrow.triangle.branch"),
                Some(&NSString::from_str("Merge branch")),
            )
        })
        .expect("macOS provides a branch SF Symbol");
        let footer = unsafe {
            NSButton::buttonWithTitle_image_target_action(
                &NSString::from_str("Choose a branch to merge"),
                &footer_image,
                Some(self),
                Some(sel!(toggleMergeBranch:)),
                mtm,
            )
        };
        footer.setFrame(NSRect::new(
            NSPoint::new(12.0, 12.0),
            NSSize::new(BRANCH_PICKER_WIDTH - 24.0, 32.0),
        ));
        footer.setBezelStyle(NSBezelStyle::AccessoryBar);
        footer.setControlSize(NSControlSize::Regular);
        footer.setImagePosition(NSCellImagePosition::ImageLeading);
        footer.setImageHugsTitle(true);
        root.addSubview(&footer);

        let controller = NSViewController::new(mtm);
        controller.setView(&root);
        controller.setPreferredContentSize(NSSize::new(BRANCH_PICKER_WIDTH, BRANCH_PICKER_HEIGHT));
        let popover = NSPopover::new(mtm);
        popover.setBehavior(NSPopoverBehavior::Transient);
        popover.setContentSize(NSSize::new(BRANCH_PICKER_WIDTH, BRANCH_PICKER_HEIGHT));
        popover.setContentViewController(Some(&controller));

        self.ivars()
            .branch_search
            .set(search)
            .expect("branch search is initialized once");
        self.ivars()
            .branch_list
            .set(list)
            .expect("branch result list is initialized once");
        self.ivars()
            .branch_footer
            .set(footer)
            .expect("branch footer is initialized once");
        self.ivars()
            .branch_popover
            .set(popover.clone())
            .expect("branch popover is initialized once");
        popover
    }

    fn update_branch_footer(&self) {
        let Some(footer) = self.ivars().branch_footer.get() else {
            return;
        };
        if self.ivars().branch_merge_mode.get() {
            footer.setTitle(&NSString::from_str("Cancel merge"));
            footer.setToolTip(Some(&NSString::from_str("Return to branch checkout")));
        } else {
            let branch = self
                .ivars()
                .repository_snapshot
                .borrow()
                .as_ref()
                .map(|snapshot| snapshot.branch.clone())
                .unwrap_or_else(|| "current branch".to_string());
            footer.setTitle(&NSString::from_str(&format!(
                "Choose a branch to merge into {branch}"
            )));
            footer.setToolTip(Some(&NSString::from_str(&format!(
                "Merge another branch into {branch}"
            ))));
        }
    }

    fn refresh_branch_results(&self, filter: &str) {
        let Some(list) = self.ivars().branch_list.get() else {
            return;
        };
        let subviews = list.subviews();
        for index in 0..subviews.count() {
            subviews.objectAtIndex(index).removeFromSuperview();
        }
        let Some(snapshot) = self.ivars().repository_snapshot.borrow().clone() else {
            return;
        };
        let filter = filter.trim().to_lowercase();
        let merge_mode = self.ivars().branch_merge_mode.get();
        let matches = |branch: &&craic_vcs::git::BranchInfo| {
            (!merge_mode || !branch.is_current)
                && (filter.is_empty() || branch.name.to_lowercase().contains(&filter))
                && !branch.name.starts_with("github-desktop-")
        };
        let default = snapshot
            .branches
            .iter()
            .enumerate()
            .filter(|(_, branch)| branch.is_default)
            .filter(|(_, branch)| matches(branch))
            .collect::<Vec<_>>();
        let mut recent = snapshot
            .branches
            .iter()
            .enumerate()
            .filter(|(_, branch)| !branch.is_default && branch.recent_order.is_some())
            .filter(|(_, branch)| matches(branch))
            .collect::<Vec<_>>();
        recent.sort_by_key(|(_, branch)| branch.recent_order);
        recent.truncate(5);
        let recent_names = recent
            .iter()
            .map(|(_, branch)| branch.name.as_str())
            .collect::<std::collections::HashSet<_>>();
        let other = snapshot
            .branches
            .iter()
            .enumerate()
            .filter(|(_, branch)| {
                !branch.is_default
                    && !recent_names.contains(branch.name.as_str())
                    && branch.recent_order.is_none()
            })
            .filter(|(_, branch)| matches(branch))
            .collect::<Vec<_>>();
        let groups = [
            ("Default branch", default),
            ("Recent branches", recent),
            ("Other branches", other),
        ];
        let result_count = groups
            .iter()
            .map(|(_, branches)| branches.len())
            .sum::<usize>();
        let header_count = groups
            .iter()
            .filter(|(_, branches)| !branches.is_empty())
            .count();
        let viewport_height = BRANCH_PICKER_HEIGHT - 108.0;
        let content_height = (result_count as f64 * BRANCH_ROW_HEIGHT + header_count as f64 * 24.0)
            .max(viewport_height);
        list.setFrameSize(NSSize::new(BRANCH_PICKER_WIDTH - 24.0, content_height));
        if result_count == 0 {
            let message = NSTextField::labelWithString(
                &NSString::from_str(if merge_mode {
                    "No branches are available to merge."
                } else {
                    "No matching branches."
                }),
                self.mtm(),
            );
            message.setFrame(NSRect::new(
                NSPoint::new(0.0, content_height - 48.0),
                NSSize::new(BRANCH_PICKER_WIDTH - 24.0, 28.0),
            ));
            message.setAlignment(NSTextAlignment::Center);
            message.setTextColor(Some(&NSColor::secondaryLabelColor()));
            list.addSubview(&message);
            return;
        }

        let mut y = content_height;
        for (group_name, branches) in groups {
            if branches.is_empty() {
                continue;
            }
            y -= 24.0;
            let heading = NSTextField::labelWithString(&NSString::from_str(group_name), self.mtm());
            heading.setFrame(NSRect::new(
                NSPoint::new(8.0, y),
                NSSize::new(BRANCH_PICKER_WIDTH - 40.0, 20.0),
            ));
            heading.setFont(Some(&NSFont::boldSystemFontOfSize(11.0)));
            heading.setTextColor(Some(&NSColor::secondaryLabelColor()));
            list.addSubview(&heading);
            for (index, branch) in branches {
                y -= BRANCH_ROW_HEIGHT;
                let symbol = if branch.is_current {
                    "checkmark.circle.fill"
                } else {
                    "arrow.triangle.branch"
                };
                let image = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                    &NSString::from_str(symbol),
                    Some(&NSString::from_str("Branch")),
                )
                .expect("macOS provides branch picker SF Symbols");
                let row = unsafe {
                    NSButton::buttonWithTitle_image_target_action(
                        &NSString::from_str(&branch.name),
                        &image,
                        Some(self),
                        Some(sel!(activateBranchRow:)),
                        self.mtm(),
                    )
                };
                row.setTag(index as isize);
                row.setFrame(NSRect::new(
                    NSPoint::new(0.0, y),
                    NSSize::new(BRANCH_PICKER_WIDTH - 24.0, BRANCH_ROW_HEIGHT),
                ));
                row.setBezelStyle(NSBezelStyle::AccessoryBar);
                row.setAlignment(NSTextAlignment::Left);
                row.setImagePosition(NSCellImagePosition::ImageLeading);
                row.setImageHugsTitle(true);
                let font = if branch.is_current {
                    NSFont::boldSystemFontOfSize(13.0)
                } else {
                    NSFont::systemFontOfSize(13.0)
                };
                row.setFont(Some(&font));
                list.addSubview(&row);
            }
        }
    }

    fn show_new_branch_sheet(&self) {
        let Some(window) = self.ivars().window.get() else {
            return;
        };
        let Some(workspace_id) = self.ivars().active_workspace_id.borrow().clone() else {
            return;
        };
        let Some(handle) = self.ivars().git_handle.borrow().clone() else {
            return;
        };
        let alert = NSAlert::new(self.mtm());
        alert.setMessageText(&NSString::from_str("New Branch"));
        alert.setInformativeText(&NSString::from_str(
            "Create and check out a branch from the current revision.",
        ));
        alert.addButtonWithTitle(&NSString::from_str("Create"));
        alert.addButtonWithTitle(&NSString::from_str("Cancel"));
        let field = NSTextField::initWithFrame(
            NSTextField::alloc(self.mtm()),
            NSRect::new(NSPoint::new(0.0, 0.0), NSSize::new(300.0, 24.0)),
        );
        field.setPlaceholderString(Some(&NSString::from_str("Branch name")));
        alert.setAccessoryView(Some(&field));
        let delegate = self.retain();
        let field_for_completion = field.clone();
        let completion = RcBlock::new(move |response| {
            if response != NSAlertFirstButtonReturn {
                return;
            }
            let branch = field_for_completion.stringValue().to_string();
            let branch = branch.trim();
            if branch.is_empty() {
                return;
            }
            let Some(requests) = delegate.ivars().repository_requests.get() else {
                return;
            };
            if let Err(error) = requests.try_send(RepositoryRequest::RunBranchAction {
                workspace_id: workspace_id.clone(),
                handle: handle.clone(),
                action: BranchAction::Create(branch.to_string()),
            }) {
                log::warn!("create branch queue rejected request error={error}");
            }
        });
        alert.beginSheetModalForWindow_completionHandler(window, Some(&completion));
        alert.window().makeFirstResponder(Some(&field));
    }

    fn refresh_changed_file_results(&self) {
        let Some(list) = self.ivars().changes_list.get() else {
            return;
        };
        let scroll = self.ivars().changes_scroll.get();
        let previous_origin = scroll
            .map(|scroll| scroll.contentView().bounds().origin)
            .unwrap_or_else(|| NSPoint::new(0.0, 0.0));
        let subviews = list.subviews();
        let first_population = subviews.count() == 0;
        for index in 0..subviews.count() {
            subviews.objectAtIndex(index).removeFromSuperview();
        }
        let Some(snapshot) = self.ivars().repository_snapshot.borrow().clone() else {
            return;
        };
        let query = self.ivars().changes_filter_query.borrow().clone();
        let visible_files = snapshot
            .changed_files
            .iter()
            .enumerate()
            .filter(|(_, file)| changed_file_matches_query(&file.path, &file.status, &query))
            .collect::<Vec<_>>();
        let viewport_height = self
            .ivars()
            .changes_scroll
            .get()
            .map(|scroll| scroll.contentView().bounds().size.height)
            .unwrap_or(480.0);
        let content_width = self
            .ivars()
            .changes_scroll
            .get()
            .map(|scroll| scroll.contentView().bounds().size.width)
            .unwrap_or(SIDEBAR_WIDTH - 20.0)
            .max(1.0);
        let content_height =
            (visible_files.len() as f64 * CHANGED_FILE_ROW_HEIGHT).max(viewport_height);
        list.setFrameSize(NSSize::new(content_width, content_height));

        let selected = self.ivars().selected_change_path.borrow().clone();
        let checked = self.ivars().checked_change_paths.borrow();
        for (visible_index, (source_index, file)) in visible_files.into_iter().enumerate() {
            let y = content_height - (visible_index as f64 + 1.0) * CHANGED_FILE_ROW_HEIGHT;
            let is_selected = selected.as_deref() == Some(file.path.as_str());
            let container = NSView::initWithFrame(
                NSView::alloc(self.mtm()),
                NSRect::new(
                    NSPoint::new(0.0, y),
                    NSSize::new(content_width, CHANGED_FILE_ROW_HEIGHT),
                ),
            );
            container.setAutoresizingMask(NSAutoresizingMaskOptions::ViewWidthSizable);
            let highlight = NSBox::initWithFrame(
                NSBox::alloc(self.mtm()),
                NSRect::new(
                    NSPoint::new(CHANGED_FILE_ROW_INSET, 1.0),
                    NSSize::new(
                        content_width - CHANGED_FILE_ROW_INSET * 2.0,
                        CHANGED_FILE_ROW_HEIGHT - 2.0,
                    ),
                ),
            );
            highlight.setBoxType(NSBoxType::Custom);
            highlight.setBorderWidth(0.0);
            highlight.setFillColor(&NSColor::unemphasizedSelectedContentBackgroundColor());
            highlight.setCornerRadius(6.0);
            highlight.setAutoresizingMask(NSAutoresizingMaskOptions::ViewWidthSizable);
            highlight.setHidden(!is_selected);
            container.addSubview(&highlight);
            // SAFETY: The target implements toggleChangedFile: with an NSButton sender.
            let check = unsafe {
                NSButton::checkboxWithTitle_target_action(
                    &NSString::new(),
                    Some(self),
                    Some(sel!(toggleChangedFile:)),
                    self.mtm(),
                )
            };
            check.setTag(source_index as isize);
            check.setFrame(NSRect::new(NSPoint::new(8.0, 4.0), NSSize::new(26.0, 28.0)));
            check.setState(if checked.contains(&file.path) {
                NSControlStateValueOn
            } else {
                NSControlStateValueOff
            });
            check.setToolTip(Some(&NSString::from_str(if checked.contains(&file.path) {
                "Include in commit"
            } else {
                "Exclude from commit"
            })));
            container.addSubview(&check);

            let (symbol, status_description) = changed_file_symbol(&file.status);
            let image = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                &NSString::from_str(symbol),
                Some(&NSString::from_str(status_description)),
            )
            .expect("macOS provides changed-file SF Symbols");
            // SAFETY: The target implements activateChangedFile: with an NSButton sender.
            let row = unsafe {
                NSButton::buttonWithTitle_target_action(
                    &NSString::from_str(&file.path),
                    Some(self),
                    Some(sel!(activateChangedFile:)),
                    self.mtm(),
                )
            };
            row.setTag(source_index as isize);
            row.setFrame(NSRect::new(
                NSPoint::new(42.0, 1.0),
                NSSize::new(content_width - 76.0, CHANGED_FILE_ROW_HEIGHT - 2.0),
            ));
            row.setAutoresizingMask(NSAutoresizingMaskOptions::ViewWidthSizable);
            row.setButtonType(NSButtonType::PushOnPushOff);
            row.setState(if is_selected {
                NSControlStateValueOn
            } else {
                NSControlStateValueOff
            });
            // Selection is drawn independently of the borderless control so
            // AppKit never changes the image/title metrics between states.
            row.setBordered(false);
            row.setAlignment(NSTextAlignment::Left);
            row.setLineBreakMode(NSLineBreakMode::ByTruncatingMiddle);
            row.setFont(Some(&NSFont::systemFontOfSize(13.0)));
            row.setToolTip(Some(&NSString::from_str(&format!(
                "{} — {}",
                file.path, status_description
            ))));
            container.addSubview(&row);
            let status = NSImageView::imageViewWithImage(&image, self.mtm());
            status.setFrame(NSRect::new(
                NSPoint::new(content_width - 28.0, 10.0),
                NSSize::new(16.0, 16.0),
            ));
            status.setAutoresizingMask(NSAutoresizingMaskOptions::ViewMinXMargin);
            let status_color = if is_selected {
                NSColor::selectedControlTextColor()
            } else {
                NSColor::secondaryLabelColor()
            };
            status.setContentTintColor(Some(&status_color));
            container.addSubview(&status);
            let file_menu = NSMenu::new(self.mtm());
            for (title, action, symbol) in [
                (
                    "Open With Default Program",
                    sel!(openChangedFile:),
                    "arrow.up.forward.app",
                ),
                (
                    "Open in Visual Studio Code",
                    sel!(openChangedFileInCode:),
                    "chevron.left.forwardslash.chevron.right",
                ),
                (
                    "Reveal in Finder",
                    sel!(revealChangedFile:),
                    "magnifyingglass",
                ),
                ("Show in Files", sel!(showChangedFileInFiles:), "folder"),
            ] {
                let item = unsafe {
                    file_menu.addItemWithTitle_action_keyEquivalent(
                        &NSString::from_str(title),
                        Some(action),
                        &NSString::new(),
                    )
                };
                item.setTag(source_index as isize);
                unsafe { item.setTarget(Some(self)) };
                if let Some(image) = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                    &NSString::from_str(symbol),
                    Some(&NSString::from_str(title)),
                ) {
                    item.setImage(Some(&image));
                }
            }

            let ignore_options = gitignore::options_for_path(&file.path, IgnoreTargetKind::File);
            if ignore_options.direct.is_some()
                || !ignore_options.folders.is_empty()
                || ignore_options.extension.is_some()
            {
                file_menu.addItem(&NSMenuItem::separatorItem(self.mtm()));
            }
            if let Some(option) = ignore_options.direct {
                let item = unsafe {
                    file_menu.addItemWithTitle_action_keyEquivalent(
                        &NSString::from_str(&option.label),
                        Some(sel!(addChangedIgnorePattern:)),
                        &NSString::new(),
                    )
                };
                unsafe {
                    item.setTarget(Some(self));
                    item.setRepresentedObject(Some(&NSString::from_str(&option.pattern)));
                }
            }
            if !ignore_options.folders.is_empty() {
                let folders = NSMenu::new(self.mtm());
                for option in ignore_options.folders {
                    let item = unsafe {
                        folders.addItemWithTitle_action_keyEquivalent(
                            &NSString::from_str(&option.label),
                            Some(sel!(addChangedIgnorePattern:)),
                            &NSString::new(),
                        )
                    };
                    unsafe {
                        item.setTarget(Some(self));
                        item.setRepresentedObject(Some(&NSString::from_str(&option.pattern)));
                    }
                }
                let folder_item = unsafe {
                    file_menu.addItemWithTitle_action_keyEquivalent(
                        &NSString::from_str("Ignore Folder (Add to .gitignore)"),
                        None,
                        &NSString::new(),
                    )
                };
                folder_item.setSubmenu(Some(&folders));
            }
            if let Some(option) = ignore_options.extension {
                let item = unsafe {
                    file_menu.addItemWithTitle_action_keyEquivalent(
                        &NSString::from_str(&option.label),
                        Some(sel!(addChangedIgnorePattern:)),
                        &NSString::new(),
                    )
                };
                unsafe {
                    item.setTarget(Some(self));
                    item.setRepresentedObject(Some(&NSString::from_str(&option.pattern)));
                }
            }

            file_menu.addItem(&NSMenuItem::separatorItem(self.mtm()));
            for (title, action, symbol) in [
                (
                    "Copy Relative Path",
                    sel!(copyChangedRelativePath:),
                    "doc.on.doc",
                ),
                (
                    "Copy Absolute Path",
                    sel!(copyChangedAbsolutePath:),
                    "doc.on.doc.fill",
                ),
            ] {
                let item = unsafe {
                    file_menu.addItemWithTitle_action_keyEquivalent(
                        &NSString::from_str(title),
                        Some(action),
                        &NSString::new(),
                    )
                };
                item.setTag(source_index as isize);
                unsafe { item.setTarget(Some(self)) };
                if let Some(image) = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                    &NSString::from_str(symbol),
                    Some(&NSString::from_str(title)),
                ) {
                    item.setImage(Some(&image));
                }
            }
            file_menu.addItem(&NSMenuItem::separatorItem(self.mtm()));
            let discard = unsafe {
                file_menu.addItemWithTitle_action_keyEquivalent(
                    &NSString::from_str("Discard Changes…"),
                    Some(sel!(confirmDiscardChangedFile:)),
                    &NSString::new(),
                )
            };
            discard.setTag(source_index as isize);
            unsafe { discard.setTarget(Some(self)) };
            if let Some(image) = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                &NSString::from_str("trash"),
                Some(&NSString::from_str("Discard Changes")),
            ) {
                discard.setImage(Some(&image));
            }
            unsafe {
                container.setMenu(Some(&file_menu));
                check.setMenu(Some(&file_menu));
                row.setMenu(Some(&file_menu));
                status.setMenu(Some(&file_menu));
            }
            list.addSubview(&container);
        }
        if let Some(scroll) = scroll {
            let clip = scroll.contentView();
            let current_bounds = clip.bounds();
            let proposed_origin = NSPoint::new(
                previous_origin.x.max(0.0),
                if first_population {
                    content_height
                } else {
                    previous_origin.y
                },
            );
            // Ask NSClipView to constrain the preserved origin so AppKit accounts for its
            // content inset and the newly rebuilt document geometry. A hand-computed clamp
            // either drops the native top inset or strands rows after the list shrinks.
            let constrained =
                clip.constrainBoundsRect(NSRect::new(proposed_origin, current_bounds.size));
            clip.scrollToPoint(constrained.origin);
            scroll.reflectScrolledClipView(&clip);
        }
        self.refresh_selection_header();
    }

    fn refresh_selection_header(&self) {
        let query = self.ivars().changes_filter_query.borrow();
        let snapshot = self.ivars().repository_snapshot.borrow();
        let checked_paths = self.ivars().checked_change_paths.borrow();
        let (total, checked) = snapshot.as_ref().map_or((0, 0), |snapshot| {
            snapshot
                .changed_files
                .iter()
                .filter(|file| changed_file_matches_query(&file.path, &file.status, &query))
                .fold((0, 0), |(total, checked), file| {
                    (
                        total + 1,
                        checked + usize::from(checked_paths.contains(&file.path)),
                    )
                })
        });
        if let Some(check) = self.ivars().select_all_check.get() {
            check.setEnabled(total > 0);
            check.setState(match (checked, total) {
                (0, _) => NSControlStateValueOff,
                (checked, total) if checked == total => NSControlStateValueOn,
                _ => NSControlStateValueMixed,
            });
        }
        if let Some(label) = self.ivars().select_all_label.get() {
            let text = match total {
                1 => "1 changed file".to_string(),
                total => format!("{total} changed files"),
            };
            label.setStringValue(&NSString::from_str(&text));
        }
    }

    fn update_repository_home(&self, snapshot: &RepositorySnapshot, running: bool) {
        let (Some(title), Some(subtitle), Some(action)) = (
            self.ivars().content_home_title.get(),
            self.ivars().content_home_subtitle.get(),
            self.ivars().content_home_action.get(),
        ) else {
            return;
        };
        title.setStringValue(&NSString::from_str(&match snapshot.changed_files.len() {
            0 => "No local changes".to_string(),
            1 => "1 changed file".to_string(),
            count => format!("{count} changed files"),
        }));
        subtitle.setStringValue(&NSString::from_str(&format!(
            "{} on {}",
            snapshot.name,
            if snapshot.branch.is_empty() {
                "an unborn branch"
            } else {
                &snapshot.branch
            }
        )));
        let remote_action = snapshot.remote_name.as_deref().and_then(|remote| {
            if !snapshot.has_upstream {
                Some("Publish branch".to_string())
            } else if snapshot.behind > 0 && snapshot.ahead > 0 {
                Some(format!("Pull & Push {remote}"))
            } else if snapshot.behind > 0 {
                Some(format!("Pull {remote}"))
            } else if snapshot.ahead > 0 {
                Some(format!("Push {remote}"))
            } else {
                None
            }
        });
        if let Some(label) = remote_action {
            action.setTitle(&NSString::from_str(&label));
            action.setToolTip(Some(&NSString::from_str(&label)));
            action.setEnabled(!running);
            action.setHidden(false);
        } else {
            action.setHidden(true);
        }
        title.setHidden(false);
        subtitle.setHidden(false);
        if let Some(empty) = self.ivars().content_empty.get() {
            empty.setHidden(true);
        }
    }

    fn hide_repository_home(&self) {
        if let Some(title) = self.ivars().content_home_title.get() {
            title.setHidden(true);
        }
        if let Some(subtitle) = self.ivars().content_home_subtitle.get() {
            subtitle.setHidden(true);
        }
        if let Some(action) = self.ivars().content_home_action.get() {
            action.setHidden(true);
        }
    }

    fn request_file_comparison(&self, path: String) {
        let Some(workspace_id) = self.ivars().active_workspace_id.borrow().clone() else {
            return;
        };
        let Some(handle) = self.ivars().git_handle.borrow().clone() else {
            return;
        };
        let Some(cancellation) = self.workspace_cancellation_token() else {
            return;
        };
        let Some(requests) = self.ivars().repository_requests.get() else {
            return;
        };
        let request_id = self.ivars().diff_request_id.get().wrapping_add(1);
        self.ivars().diff_request_id.set(request_id);
        self.ivars().diff_loading_request_id.set(Some(request_id));
        self.ivars().loaded_diff_path.borrow_mut().take();
        self.ivars().loaded_image_path.borrow_mut().take();
        let cached = {
            let mut cache = self.ivars().file_preview_cache.borrow_mut();
            cache
                .iter()
                .position(|entry| entry.path == path)
                .and_then(|index| cache.remove(index))
                .map(|entry| {
                    let content = entry.content.clone();
                    cache.push_back(entry);
                    content
                })
        };
        if let Some(cached) = cached {
            log::debug!("native file preview cache hit path={path}");
            match cached {
                CachedFilePreviewContent::Diff(prepared) => {
                    self.apply_file_comparison(&workspace_id, &path, request_id, Ok(prepared))
                }
                CachedFilePreviewContent::Image(comparison) => self.apply_file_bytes_comparison(
                    &workspace_id,
                    &path,
                    request_id,
                    Ok(comparison),
                ),
                CachedFilePreviewContent::Unavailable(message) => {
                    self.ivars().diff_loading_request_id.set(None);
                    self.show_file_comparison_error(&message);
                }
            }
            return;
        }
        self.show_file_comparison_loading(&path);
        let request = if is_changed_binary_preview_path(&path) {
            RepositoryRequest::LoadFileBytesComparison {
                workspace_id,
                handle,
                path,
                request_id,
                cancellation,
            }
        } else {
            RepositoryRequest::LoadFileComparison {
                workspace_id,
                handle,
                path,
                request_id,
                cancellation,
            }
        };
        if let Err(error) = requests.try_send(request) {
            log::warn!("file comparison queue rejected request error={error}");
            if self.ivars().diff_request_id.get() == request_id {
                self.ivars().diff_loading_request_id.set(None);
                self.show_file_comparison_error("Unable to queue diff load");
            }
        }
    }

    fn show_file_comparison_loading(&self, path: &str) {
        log::debug!("native file comparison loading path={path}");
        self.hide_repository_home();
        if let Some(empty) = self.ivars().content_empty.get() {
            empty.setHidden(true);
        }
        if let Some(diff_view) = self.ivars().diff_view.get() {
            diff_view.setHidden(true);
        }
        if let Some(image) = self.ivars().image_preview.get() {
            image.setHidden(true);
        }
        if let Some(binary) = self.ivars().binary_preview.get() {
            binary.setHidden(true);
        }
        if let Some(spinner) = self.ivars().diff_spinner.get() {
            spinner.setHidden(false);
            // SAFETY: The retained progress indicator is animated on the AppKit main thread.
            unsafe { spinner.startAnimation(None) };
        }
    }

    fn apply_file_comparison(
        &self,
        workspace_id: &str,
        path: &str,
        request_id: u64,
        result: Result<PreparedDiff, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id)
            || self.ivars().diff_request_id.get() != request_id
            || self.ivars().selected_change_path.borrow().as_deref() != Some(path)
        {
            log::debug!(
                "discarding stale file comparison workspace={} path={} request_id={}",
                workspace_id,
                path,
                request_id
            );
            return;
        }
        if let Some(spinner) = self.ivars().diff_spinner.get() {
            // SAFETY: The retained progress indicator is animated on the AppKit main thread.
            unsafe { spinner.stopAnimation(None) };
            spinner.setHidden(true);
        }
        self.ivars().diff_loading_request_id.set(None);
        match result {
            Ok(prepared) => {
                self.cache_file_preview(path, CachedFilePreviewContent::Diff(prepared.clone()));
                self.ivars()
                    .loaded_diff_path
                    .replace(Some(path.to_string()));
                if let Some(diff_view) = self.ivars().diff_view.get() {
                    diff_view.set_document(
                        path,
                        prepared.fingerprint,
                        prepared.document,
                        prepared.syntax,
                    );
                    diff_view.setHidden(!self.is_active_page("changes"));
                }
                if let Some(binary) = self.ivars().binary_preview.get() {
                    binary.setHidden(true);
                }
                if self.is_active_page("changes")
                    && let Some(empty) = self.ivars().content_empty.get()
                {
                    empty.setHidden(true);
                }
                log::info!(
                    "native Skia Metal file comparison applied workspace={} path={} source_rows={} fingerprint={:016x}",
                    workspace_id,
                    path,
                    prepared.source_rows,
                    prepared.fingerprint
                );
            }
            Err(error) => {
                self.ivars().loaded_diff_path.borrow_mut().take();
                if is_preview_limit_message(&error) {
                    self.cache_file_preview(
                        path,
                        CachedFilePreviewContent::Unavailable(error.clone()),
                    );
                }
                self.show_file_comparison_error(&error);
                log::warn!(
                    "native file comparison failed workspace={} path={}: {}",
                    workspace_id,
                    path,
                    error
                );
            }
        }
    }

    fn apply_file_bytes_comparison(
        &self,
        workspace_id: &str,
        path: &str,
        request_id: u64,
        result: Result<BytesComparison, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id)
            || self.ivars().diff_request_id.get() != request_id
            || self.ivars().selected_change_path.borrow().as_deref() != Some(path)
        {
            log::debug!(
                "discarding stale image comparison workspace={} path={} request_id={}",
                workspace_id,
                path,
                request_id
            );
            return;
        }
        if let Some(spinner) = self.ivars().diff_spinner.get() {
            unsafe { spinner.stopAnimation(None) };
            spinner.setHidden(true);
        }
        self.ivars().diff_loading_request_id.set(None);
        let comparison = match result {
            Ok(comparison) => comparison,
            Err(error) => {
                self.ivars().loaded_image_path.borrow_mut().take();
                if is_preview_limit_message(&error) {
                    self.cache_file_preview(
                        path,
                        CachedFilePreviewContent::Unavailable(error.clone()),
                    );
                }
                self.show_file_comparison_error(&error);
                log::warn!(
                    "native binary comparison failed workspace={} path={}: {}",
                    workspace_id,
                    path,
                    error
                );
                return;
            }
        };
        if let Err(error) = self.apply_changed_binary_preview(path, &comparison) {
            self.ivars().loaded_image_path.borrow_mut().take();
            self.show_file_comparison_error(&error);
            log::warn!(
                "native binary preview failed workspace={workspace_id} path={path}: {error}"
            );
            return;
        }
        self.cache_file_preview(path, CachedFilePreviewContent::Image(comparison));
        self.ivars()
            .loaded_image_path
            .replace(Some(path.to_string()));
        if self.is_active_page("changes")
            && let Some(empty) = self.ivars().content_empty.get()
        {
            empty.setHidden(true);
        }
        log::info!("native binary preview applied workspace={workspace_id} path={path}");
    }

    fn apply_changed_binary_preview(
        &self,
        path: &str,
        comparison: &BytesComparison,
    ) -> Result<(), String> {
        let Some(root) = self.ivars().binary_preview.get() else {
            return Err("The native binary comparison view is unavailable.".to_string());
        };
        let registrations = self.populate_native_binary_comparison(root, path, comparison)?;
        self.ivars()
            .binary_font_registrations
            .replace(registrations);
        if let Some(image) = self.ivars().image_preview.get() {
            image.setHidden(true);
        }
        if let Some(diff) = self.ivars().diff_view.get() {
            diff.setHidden(true);
        }
        root.setHidden(!self.is_active_page("changes"));
        Ok(())
    }

    fn populate_native_binary_comparison(
        &self,
        root: &NSView,
        path: &str,
        comparison: &BytesComparison,
    ) -> Result<Vec<NativeFontRegistration>, String> {
        let subviews = root.subviews();
        for index in (0..subviews.count()).rev() {
            subviews.objectAtIndex(index).removeFromSuperview();
        }
        if comparison.before.is_none() && comparison.after.is_none() {
            return Err("No file content is available to preview.".to_string());
        }

        let bounds = root.bounds();
        let title = NSTextField::labelWithString(&NSString::from_str(path), self.mtm());
        title.setFrame(NSRect::new(
            NSPoint::new(18.0, bounds.size.height - 38.0),
            NSSize::new((bounds.size.width - 36.0).max(1.0), 22.0),
        ));
        title.setAutoresizingMask(
            NSAutoresizingMaskOptions::ViewWidthSizable | NSAutoresizingMaskOptions::ViewMinYMargin,
        );
        title.setFont(Some(&NSFont::boldSystemFontOfSize(13.0)));
        title.setLineBreakMode(NSLineBreakMode::ByTruncatingMiddle);
        title.setToolTip(Some(&NSString::from_str(path)));
        root.addSubview(&title);

        let preview_frame = NSRect::new(
            NSPoint::new(12.0, 12.0),
            NSSize::new(
                (bounds.size.width - 24.0).max(1.0),
                (bounds.size.height - 56.0).max(1.0),
            ),
        );
        let split = NSSplitView::initWithFrame(NSSplitView::alloc(self.mtm()), preview_frame);
        split.setVertical(true);
        split.setDividerStyle(NSSplitViewDividerStyle::Thin);
        split.setAutoresizingMask(
            NSAutoresizingMaskOptions::ViewWidthSizable
                | NSAutoresizingMaskOptions::ViewHeightSizable,
        );
        let mut registrations = Vec::new();
        let mut add_pane = |label: &str, bytes: &[u8]| {
            let (pane, registration) = self.make_changed_binary_pane(path, label, bytes);
            if let Some(registration) = registration {
                registrations.push(registration);
            }
            split.addArrangedSubview(&pane);
        };
        match (&comparison.before, &comparison.after) {
            (None, Some(after)) => {
                add_pane("Added", after);
            }
            (Some(before), None) => {
                add_pane("Deleted", before);
            }
            (Some(before), Some(after)) => {
                add_pane("Before", before);
                add_pane("After", after);
            }
            (None, None) => unreachable!(),
        }
        drop(add_pane);
        split.adjustSubviews();
        root.addSubview(&split);
        Ok(registrations)
    }

    fn make_changed_binary_pane(
        &self,
        path: &str,
        label: &str,
        bytes: &[u8],
    ) -> (Retained<NSView>, Option<NativeFontRegistration>) {
        let pane = NSView::initWithFrame(
            NSView::alloc(self.mtm()),
            NSRect::new(NSPoint::ZERO, NSSize::new(420.0, 600.0)),
        );
        pane.setAutoresizingMask(
            NSAutoresizingMaskOptions::ViewWidthSizable
                | NSAutoresizingMaskOptions::ViewHeightSizable,
        );
        let heading = NSTextField::labelWithString(&NSString::from_str(label), self.mtm());
        heading.setFrame(NSRect::new(
            NSPoint::new(8.0, 572.0),
            NSSize::new(404.0, 20.0),
        ));
        heading.setAutoresizingMask(
            NSAutoresizingMaskOptions::ViewWidthSizable | NSAutoresizingMaskOptions::ViewMinYMargin,
        );
        heading.setAlignment(NSTextAlignment::Center);
        heading.setFont(Some(&NSFont::boldSystemFontOfSize(11.0)));
        heading.setTextColor(Some(&NSColor::secondaryLabelColor()));
        pane.addSubview(&heading);
        let frame = NSRect::new(NSPoint::new(8.0, 8.0), NSSize::new(404.0, 556.0));

        let mut font_registration = None;
        let result: Result<Retained<NSView>, String> = if is_image_preview_path(path) {
            NSImage::initWithData(NSImage::alloc(), &NSData::with_bytes(bytes))
                .map(|image| {
                    let view = NSImageView::imageViewWithImage(&image, self.mtm());
                    view.setFrame(frame);
                    view.setImageScaling(NSImageScaling::ScaleProportionallyUpOrDown);
                    view.setAccessibilityLabel(Some(&NSString::from_str(&format!(
                        "{label} image"
                    ))));
                    Retained::into_super(Retained::into_super(view))
                })
                .ok_or_else(|| "macOS could not decode this image.".to_string())
        } else if is_pdf_preview_path(path) {
            let data = NSData::with_bytes(bytes);
            let document = unsafe { PDFDocument::initWithData(PDFDocument::alloc(), &data) }
                .ok_or_else(|| "macOS could not decode this PDF.".to_string());
            document.map(|document| {
                let view = unsafe { PDFView::initWithFrame(PDFView::alloc(self.mtm()), frame) };
                unsafe {
                    view.setAutoScales(true);
                    view.setDisplayMode(PDFDisplayMode::SinglePageContinuous);
                    view.setDisplayDirection(PDFDisplayDirection::Vertical);
                    view.setDocument(Some(&document));
                }
                Retained::into_super(view)
            })
        } else if let Some(mime) = media_preview_mime(path) {
            let configuration =
                unsafe { WKWebViewConfiguration::init(WKWebViewConfiguration::alloc(self.mtm())) };
            unsafe {
                configuration
                    .defaultWebpagePreferences()
                    .setAllowsContentJavaScript(false)
            };
            let view = unsafe {
                WKWebView::initWithFrame_configuration(
                    WKWebView::alloc(self.mtm()),
                    frame,
                    &configuration,
                )
            };
            unsafe { view.setNavigationDelegate(Some(ProtocolObject::from_ref(self))) };
            let base_url = NSURL::URLWithString(&NSString::from_str("about:blank"))
                .expect("about:blank is a valid URL");
            unsafe {
                view.loadData_MIMEType_characterEncodingName_baseURL(
                    &NSData::with_bytes(bytes),
                    &NSString::from_str(mime),
                    &NSString::from_str("utf-8"),
                    &base_url,
                )
            };
            Ok(Retained::into_super(view))
        } else if is_font_preview_path(path) {
            self.make_changed_font_preview(bytes, frame)
                .map(|(view, registration)| {
                    font_registration = Some(registration);
                    Retained::into_super(view)
                })
        } else {
            Err("A native preview is not available for this binary file.".to_string())
        };

        match result {
            Ok(view) => {
                view.setAutoresizingMask(
                    NSAutoresizingMaskOptions::ViewWidthSizable
                        | NSAutoresizingMaskOptions::ViewHeightSizable,
                );
                pane.addSubview(&view);
            }
            Err(message) => {
                let error =
                    NSTextField::wrappingLabelWithString(&NSString::from_str(&message), self.mtm());
                error.setFrame(NSRect::new(
                    NSPoint::new(24.0, 260.0),
                    NSSize::new(372.0, 52.0),
                ));
                error.setAutoresizingMask(
                    NSAutoresizingMaskOptions::ViewWidthSizable
                        | NSAutoresizingMaskOptions::ViewMinYMargin
                        | NSAutoresizingMaskOptions::ViewMaxYMargin,
                );
                error.setAlignment(NSTextAlignment::Center);
                error.setTextColor(Some(&NSColor::secondaryLabelColor()));
                pane.addSubview(&error);
            }
        }
        (pane, font_registration)
    }

    fn make_changed_font_preview(
        &self,
        bytes: &[u8],
        frame: NSRect,
    ) -> Result<(Retained<NSScrollView>, NativeFontRegistration), String> {
        let length = isize::try_from(bytes.len())
            .map_err(|_| "This font is too large for Core Graphics.".to_string())?;
        let data = unsafe { CFData::new(None, bytes.as_ptr(), length) }
            .ok_or_else(|| "macOS could not create font data.".to_string())?;
        let descriptor = unsafe { CTFontManagerCreateFontDescriptorFromData(&data) }
            .ok_or_else(|| "macOS could not decode this font.".to_string())?;
        let descriptors = unsafe { CTFontManagerCreateFontDescriptorsFromData(&data) };
        if descriptors.count() == 0 {
            return Err("macOS could not find a font face in this file.".to_string());
        }
        unsafe {
            CTFontManagerRegisterFontDescriptors(
                &descriptors,
                CTFontManagerScope::Process,
                true,
                None,
            );
        }
        let registration = NativeFontRegistration { descriptors };
        let font = unsafe { CTFont::with_font_descriptor(&descriptor, 12.0, std::ptr::null()) };
        let post_script_name = unsafe { font.post_script_name() }.to_string();
        let display_name = unsafe { font.full_name() }.to_string();
        let mut content = String::new();
        let mut ranges = Vec::new();
        let mut append_line = |text: &str, size: f64| {
            let start = content.encode_utf16().count();
            content.push_str(text);
            let length = content.encode_utf16().count() - start;
            ranges.push((NSRange::new(start, length), size));
            content.push('\n');
        };
        append_line(&display_name, 30.0);
        append_line("abcdefghijklmnopqrstuvwxyz", 26.0);
        append_line("ABCDEFGHIJKLMNOPQRSTUVWXYZ", 26.0);
        append_line("0123456789 .:,;(*!?')", 26.0);
        for size in [12.0, 18.0, 24.0, 36.0, 48.0, 72.0] {
            append_line("Sphinx of black quartz, judge my vow.", size);
        }
        let text = NSTextView::initWithFrame(
            NSTextView::alloc(self.mtm()),
            NSRect::new(NSPoint::ZERO, NSSize::new(frame.size.width, 920.0)),
        );
        text.setString(&NSString::from_str(&content));
        text.setEditable(false);
        text.setSelectable(true);
        text.setDrawsBackground(false);
        text.setTextContainerInset(NSSize::new(18.0, 18.0));
        let storage = unsafe { text.textStorage() }
            .ok_or_else(|| "macOS could not create font preview text storage.".to_string())?;
        storage.beginEditing();
        for (range, size) in ranges {
            let Some(font) =
                NSFont::fontWithName_size(&NSString::from_str(&post_script_name), size)
            else {
                storage.endEditing();
                return Err(format!("macOS could not activate {display_name}."));
            };
            unsafe { storage.addAttribute_value_range(NSFontAttributeName, &font, range) };
        }
        storage.endEditing();
        let scroll = NSScrollView::initWithFrame(NSScrollView::alloc(self.mtm()), frame);
        scroll.setBorderType(NSBorderType::NoBorder);
        scroll.setDrawsBackground(false);
        scroll.setHasVerticalScroller(true);
        scroll.setAutohidesScrollers(true);
        scroll.setDocumentView(Some(&text));
        Ok((scroll, registration))
    }

    fn clear_changed_binary_preview(&self) {
        if let Some(root) = self.ivars().binary_preview.get() {
            root.setHidden(true);
            let subviews = root.subviews();
            for index in (0..subviews.count()).rev() {
                subviews.objectAtIndex(index).removeFromSuperview();
            }
        }
        self.ivars().binary_font_registrations.borrow_mut().clear();
    }

    fn cache_file_preview(&self, path: &str, content: CachedFilePreviewContent) {
        let mut cache = self.ivars().file_preview_cache.borrow_mut();
        if let Some(index) = cache.iter().position(|entry| entry.path == path) {
            cache.remove(index);
        }
        cache.push_back(CachedFilePreview {
            path: path.to_string(),
            content,
        });
        while cache.len() > FILE_PREVIEW_CACHE_CAPACITY {
            cache.pop_front();
        }
    }

    fn show_file_comparison_error(&self, message: &str) {
        self.hide_repository_home();
        if let Some(diff_view) = self.ivars().diff_view.get() {
            diff_view.setHidden(true);
        }
        if let Some(image) = self.ivars().image_preview.get() {
            image.setHidden(true);
        }
        if let Some(binary) = self.ivars().binary_preview.get() {
            binary.setHidden(true);
        }
        if self.is_active_page("changes")
            && let Some(empty) = self.ivars().content_empty.get()
        {
            empty.setStringValue(&NSString::from_str(message));
            empty.setHidden(false);
        }
    }

    fn is_active_page(&self, page_id: &str) -> bool {
        self.ivars().active_page_id.borrow().as_deref() == Some(page_id)
    }

    fn request_history_avatar(&self, email: &str) {
        let email = email.trim();
        if email.is_empty() {
            return;
        }
        let cache_key = format!("email:{}", email.to_ascii_lowercase());
        self.request_avatar(cache_key, AvatarSource::Email(email.to_string()));
    }

    fn request_avatar(&self, cache_key: String, source: AvatarSource) {
        if self.ivars().avatar_images.borrow().contains_key(&cache_key)
            || !self
                .ivars()
                .avatar_in_flight
                .borrow_mut()
                .insert(cache_key.clone())
        {
            return;
        }
        let Some(requests) = self.ivars().repository_requests.get() else {
            self.ivars()
                .avatar_in_flight
                .borrow_mut()
                .remove(&cache_key);
            return;
        };
        let Some(handle) = self.ivars().git_handle.borrow().clone() else {
            self.ivars()
                .avatar_in_flight
                .borrow_mut()
                .remove(&cache_key);
            return;
        };
        if let Err(error) = requests.try_send(RepositoryRequest::LoadAvatar {
            cache_key: cache_key.clone(),
            source,
            handle,
        }) {
            self.ivars()
                .avatar_in_flight
                .borrow_mut()
                .remove(&cache_key);
            log::debug!("avatar request coalesced key={cache_key} error={error}");
        }
    }

    fn apply_avatar(&self, cache_key: &str, result: Result<Vec<u8>, String>) {
        self.ivars().avatar_in_flight.borrow_mut().remove(cache_key);
        let bytes = match result {
            Ok(bytes) => bytes,
            Err(error) => {
                log::debug!("avatar unavailable key={cache_key} error={error}");
                return;
            }
        };
        let data = NSData::with_bytes(&bytes);
        let Some(image) = NSImage::initWithData(NSImage::alloc(), &data) else {
            log::debug!("avatar decode failed key={cache_key}");
            return;
        };
        self.ivars()
            .avatar_images
            .borrow_mut()
            .insert(cache_key.to_string(), image.clone());
        if let Some(history) = self.ivars().history.get() {
            history.table.reloadData();
            if history.avatar_source.borrow().as_deref() == Some(cache_key) {
                history.avatar.setImage(Some(&image));
                history.avatar.setHidden(false);
            }
        }
        if self.ivars().commit_avatar_source.borrow().as_deref() == Some(cache_key)
            && let Some(composer) = self.ivars().commit_composer.get()
        {
            let snapshot = self.ivars().repository_snapshot.borrow();
            let warning = snapshot
                .as_ref()
                .and_then(RepositorySnapshot::remote_author_warning_text);
            composer.set_author(
                snapshot
                    .as_ref()
                    .and_then(|snapshot| snapshot.user_name.as_deref()),
                Some(&image),
                warning.as_deref(),
            );
            log::debug!("native commit author avatar applied key={cache_key}");
        }
        if self
            .ivars()
            .author_popover
            .get()
            .is_some_and(|popover| popover.isShown())
            && let Some(table) = self.ivars().author_table.get()
        {
            table.reloadData();
        }
    }

    fn reset_history(&self, message: &str) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        history
            .generation
            .set(history.generation.get().wrapping_add(1));
        history.commits.borrow_mut().clear();
        history.files.borrow_mut().clear();
        history.cursor.borrow_mut().take();
        history.selected_hash.borrow_mut().take();
        history.selected_file.borrow_mut().take();
        history.loaded_diff_path.borrow_mut().take();
        history.loaded_binary_path.borrow_mut().take();
        history.preview_cache.borrow_mut().clear();
        history.has_more.set(false);
        history.loading.set(false);
        history.table.reloadData();
        // SAFETY: The nil sender only clears this table's native selection state.
        unsafe { history.table.deselectAll(None) };
        history.files_table.reloadData();
        // SAFETY: The nil sender only clears the native file-table selection.
        unsafe { history.files_table.deselectAll(None) };
        history.diff.clear();
        history.diff.setHidden(true);
        self.clear_history_binary_preview();
        history
            .title
            .setStringValue(&NSString::from_str("Select a commit"));
        history.avatar.setHidden(true);
        history.avatar_source.borrow_mut().take();
        history.metadata.setStringValue(&NSString::new());
        history.added.setHidden(true);
        history.deleted.setHidden(true);
        history.comment.setStringValue(&NSString::new());
        history
            .file_count
            .setStringValue(&NSString::from_str("No commit selected"));
        history.copy_hash.setEnabled(false);
        history.open_remote.setEnabled(false);
        history.empty.setStringValue(&NSString::from_str(message));
        history.empty.setHidden(false);
        history.status.setStringValue(&NSString::from_str(message));
        history.status.setHidden(false);
        // SAFETY: The spinner is retained by HistoryUi and only driven on AppKit's main thread.
        if message.starts_with("Loading") {
            unsafe { history.loading_spinner.startAnimation(None) };
        } else {
            unsafe { history.loading_spinner.stopAnimation(None) };
        }
    }

    fn clear_history_binary_preview(&self) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        history.binary_preview.setHidden(true);
        let subviews = history.binary_preview.subviews();
        for index in (0..subviews.count()).rev() {
            subviews.objectAtIndex(index).removeFromSuperview();
        }
        history.binary_font_registrations.borrow_mut().clear();
    }

    fn request_history_page(&self, reset: bool) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        if history.loading.get() {
            return;
        }
        if reset {
            history
                .generation
                .set(history.generation.get().wrapping_add(1));
            history.commits.borrow_mut().clear();
            history.cursor.borrow_mut().take();
            history.selected_hash.borrow_mut().take();
            history.selected_file.borrow_mut().take();
            history.loaded_diff_path.borrow_mut().take();
            history.loaded_binary_path.borrow_mut().take();
            history.preview_cache.borrow_mut().clear();
            history.table.reloadData();
            history.diff.clear();
            history.diff.setHidden(true);
            self.clear_history_binary_preview();
            history
                .empty
                .setStringValue(&NSString::from_str("Loading commits..."));
            history.empty.setHidden(false);
        } else if !history.has_more.get() {
            return;
        }
        let Some(workspace_id) = self.ivars().active_workspace_id.borrow().clone() else {
            history
                .status
                .setStringValue(&NSString::from_str("No workspace"));
            return;
        };
        let Some(handle) = self.ivars().git_handle.borrow().clone() else {
            history
                .status
                .setStringValue(&NSString::from_str("No Git repository"));
            return;
        };
        let Some(cancellation) = self.workspace_cancellation_token() else {
            return;
        };
        let Some(requests) = self.ivars().repository_requests.get() else {
            history
                .status
                .setStringValue(&NSString::from_str("History service unavailable"));
            return;
        };
        history.loading.set(true);
        self.set_page_badge("history", NativePageBadge::Indicator);
        let empty = history.commits.borrow().is_empty();
        let search_active = !history.query.borrow().is_empty();
        if empty {
            history
                .loading_spinner
                .setControlSize(NSControlSize::Regular);
            history
                .loading_spinner
                .setFrameSize(NSSize::new(24.0, 24.0));
            // SAFETY: The retained empty-state spinner is driven on AppKit's main thread.
            unsafe { history.loading_spinner.startAnimation(None) };
            history
                .status
                .setStringValue(&NSString::from_str(if search_active {
                    "Searching commits..."
                } else {
                    "Loading commits..."
                }));
            history.status.setHidden(false);
        } else {
            // Pagination is represented by a real final table row so the indicator scrolls
            // with the commit cards instead of floating over the viewport.
            unsafe { history.loading_spinner.stopAnimation(None) };
            history.status.setHidden(true);
            history.table.reloadData();
        }
        self.layout_sidebar();
        let request = RepositoryRequest::LoadHistoryPage {
            workspace_id,
            handle,
            query: history.query.borrow().clone(),
            after: history.cursor.borrow().clone(),
            generation: history.generation.get(),
            cancellation,
        };
        if let Err(error) = requests.try_send(request) {
            history.loading.set(false);
            // SAFETY: The retained spinner is driven on AppKit's main thread.
            unsafe { history.loading_spinner.stopAnimation(None) };
            history.table.reloadData();
            history.status.setHidden(false);
            history
                .status
                .setStringValue(&NSString::from_str("Unable to queue history load"));
            self.layout_sidebar();
            self.set_page_badge("history", NativePageBadge::None);
            log::warn!("history page queue rejected request error={error}");
        }
    }

    fn apply_history_page(
        &self,
        workspace_id: &str,
        generation: u64,
        result: Result<CommitPage, String>,
    ) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id)
            || history.generation.get() != generation
        {
            log::debug!("discarding stale history page workspace={workspace_id}");
            return;
        }
        history.loading.set(false);
        self.set_page_badge("history", NativePageBadge::None);
        // SAFETY: The retained spinner is driven on AppKit's main thread.
        unsafe { history.loading_spinner.stopAnimation(None) };
        if history.pending_search.replace(false) {
            self.request_history_page(true);
            return;
        }
        match result {
            Ok(page) => {
                history.has_more.set(page.has_more);
                let mut commits = history.commits.borrow_mut();
                for commit in page.commits {
                    if !commits
                        .iter()
                        .any(|candidate| candidate.hash == commit.hash)
                    {
                        commits.push(commit);
                    }
                }
                history
                    .cursor
                    .replace(commits.last().map(|commit| commit.hash.clone()));
                let count = commits.len();
                drop(commits);
                history.table.reloadData();
                if count == 0 {
                    history.status.setHidden(false);
                    history.status.setStringValue(&NSString::from_str(
                        if history.query.borrow().is_empty() {
                            "History is empty."
                        } else {
                            "No matching commits."
                        },
                    ));
                } else if history.query.borrow().is_empty() {
                    history.status.setHidden(true);
                } else {
                    history.status.setHidden(false);
                    history.status.setStringValue(&NSString::from_str(
                        if history.has_more.get() {
                            format!("{count} loaded, more available")
                        } else {
                            format!("{count} matches")
                        }
                        .as_str(),
                    ));
                }
                if count > 0 && history.selected_hash.borrow().is_none() {
                    let first = NSIndexSet::indexSetWithIndex(0);
                    history
                        .table
                        .selectRowIndexes_byExtendingSelection(&first, false);
                    self.select_history_commit(0);
                }
            }
            Err(error) => {
                history.has_more.set(false);
                history.status.setHidden(false);
                history.status.setStringValue(&NSString::from_str(&error));
                history
                    .empty
                    .setStringValue(&NSString::from_str("Unable to load history"));
                history.empty.setHidden(false);
                log::warn!("native history page failed workspace={workspace_id}: {error}");
            }
        }
        self.layout_sidebar();
    }

    fn select_history_commit(&self, index: usize) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        let Some(commit) = history.commits.borrow().get(index).cloned() else {
            return;
        };
        if history.selected_hash.borrow().as_deref() == Some(commit.hash.as_str()) {
            return;
        }
        history.selected_hash.replace(Some(commit.hash.clone()));
        history.selected_file.borrow_mut().take();
        history.loaded_diff_path.borrow_mut().take();
        history.loaded_binary_path.borrow_mut().take();
        history.files.borrow_mut().clear();
        history
            .detail_request_id
            .set(history.detail_request_id.get().wrapping_add(1));
        history
            .title
            .setStringValue(&NSString::from_str(&commit.subject));
        history
            .metadata
            .setStringValue(&NSString::from_str("Loading commit details…"));
        history.avatar.setHidden(true);
        history.avatar_source.borrow_mut().take();
        history.added.setHidden(true);
        history.deleted.setHidden(true);
        history.comment.setStringValue(&NSString::new());
        history
            .file_count
            .setStringValue(&NSString::from_str("Loading changed files…"));
        history.files_table.reloadData();
        history.copy_hash.setEnabled(false);
        history.open_remote.setEnabled(false);
        history.diff.clear();
        history.diff.setHidden(true);
        self.clear_history_binary_preview();
        history
            .empty
            .setStringValue(&NSString::from_str("Loading commit…"));
        history.empty.setHidden(false);
        let Some(workspace_id) = self.ivars().active_workspace_id.borrow().clone() else {
            return;
        };
        let Some(handle) = self.ivars().git_handle.borrow().clone() else {
            return;
        };
        let Some(cancellation) = self.workspace_cancellation_token() else {
            return;
        };
        let Some(requests) = self.ivars().repository_requests.get() else {
            return;
        };
        let request = RepositoryRequest::LoadHistoryCommit {
            workspace_id,
            handle,
            hash: commit.hash,
            request_id: history.detail_request_id.get(),
            cancellation,
        };
        if let Err(error) = requests.try_send(request) {
            history
                .empty
                .setStringValue(&NSString::from_str("Unable to queue commit details"));
            log::warn!("history detail queue rejected request error={error}");
        }
    }

    fn apply_history_commit(
        &self,
        workspace_id: &str,
        hash: &str,
        request_id: u64,
        result: Result<(Commit, Vec<ChangedFile>), String>,
    ) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id)
            || history.detail_request_id.get() != request_id
            || history.selected_hash.borrow().as_deref() != Some(hash)
        {
            return;
        }
        match result {
            Ok((commit, files)) => {
                history
                    .title
                    .setStringValue(&NSString::from_str(&commit.subject));
                history
                    .metadata
                    .setStringValue(&NSString::from_str(&format!(
                        "{}  ·  {}  ·  {}",
                        commit.author, commit.short_hash, commit.relative_time
                    )));
                let avatar_key = commit.author_email.as_deref().and_then(history_avatar_key);
                history.avatar_source.replace(avatar_key.clone());
                let avatar_image = avatar_key
                    .as_deref()
                    .and_then(|key| self.ivars().avatar_images.borrow().get(key).cloned())
                    .or_else(|| {
                        NSImage::imageWithSystemSymbolName_accessibilityDescription(
                            &NSString::from_str("person.crop.circle.fill"),
                            Some(&NSString::from_str(&commit.author)),
                        )
                    });
                history.avatar.setImage(avatar_image.as_deref());
                history
                    .avatar
                    .setToolTip(Some(&NSString::from_str(&commit.author)));
                history.avatar.setHidden(false);
                if let Some(email) = commit.author_email.as_deref() {
                    self.request_history_avatar(email);
                }
                history
                    .added
                    .setStringValue(&NSString::from_str(&format!("+{}", commit.insertions)));
                history
                    .deleted
                    .setStringValue(&NSString::from_str(&format!("−{}", commit.deletions)));
                history.added.setHidden(false);
                history.deleted.setHidden(false);
                history
                    .comment
                    .setStringValue(&NSString::from_str(&commit.comment));
                history.copy_hash.setEnabled(true);
                history.open_remote.setEnabled(
                    self.ivars()
                        .repository_snapshot
                        .borrow()
                        .as_ref()
                        .and_then(|snapshot| snapshot.remote_url.as_ref())
                        .is_some(),
                );
                history.files.replace(files);
                let file_count = history.files.borrow().len();
                history
                    .file_count
                    .setStringValue(&NSString::from_str(&match file_count {
                        1 => "1 changed file".to_string(),
                        count => format!("{count} changed files"),
                    }));
                self.refresh_history_files();
                if history.files.borrow().is_empty() {
                    history
                        .empty
                        .setStringValue(&NSString::from_str("No changed files"));
                    history.empty.setHidden(false);
                } else {
                    let first = NSIndexSet::indexSetWithIndex(0);
                    history
                        .files_table
                        .selectRowIndexes_byExtendingSelection(&first, false);
                }
            }
            Err(error) => {
                history.avatar.setHidden(true);
                history.avatar_source.borrow_mut().take();
                history.added.setHidden(true);
                history.deleted.setHidden(true);
                history
                    .metadata
                    .setStringValue(&NSString::from_str("Unable to load commit details"));
                history
                    .file_count
                    .setStringValue(&NSString::from_str("Changed files unavailable"));
                history
                    .empty
                    .setStringValue(&NSString::from_str("Unable to load commit"));
                history.empty.setHidden(false);
                log::warn!("native history commit failed hash={hash}: {error}");
            }
        }
    }

    fn refresh_history_files(&self) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        history.files_table.reloadData();
        let viewport = history.files_scroll.contentSize();
        let row_pitch =
            history.files_table.rowHeight() + history.files_table.intercellSpacing().height;
        let document_height = (history.files.borrow().len() as f64 * row_pitch)
            .max(viewport.height)
            .max(1.0);
        history
            .files_table
            .setFrameSize(NSSize::new(viewport.width.max(1.0), document_height));
        log::debug!(
            "history file pane geometry rows={} viewport_height={} document_height={}",
            history.files.borrow().len(),
            viewport.height,
            document_height
        );
        if let Some(selected) = history.selected_file.borrow().as_deref()
            && let Some(index) = history
                .files
                .borrow()
                .iter()
                .position(|file| file.path == selected)
        {
            let selection = NSIndexSet::indexSetWithIndex(index);
            history
                .files_table
                .selectRowIndexes_byExtendingSelection(&selection, false);
        }
    }

    fn request_history_comparison(&self, index: usize) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        let Some(file) = history.files.borrow().get(index).cloned() else {
            return;
        };
        let Some(hash) = history.selected_hash.borrow().clone() else {
            return;
        };
        history.selected_file.replace(Some(file.path.clone()));
        history.loaded_diff_path.borrow_mut().take();
        history.loaded_binary_path.borrow_mut().take();
        history
            .comparison_request_id
            .set(history.comparison_request_id.get().wrapping_add(1));
        let request_id = history.comparison_request_id.get();
        history.diff.setHidden(true);
        history.binary_preview.setHidden(true);
        let cached = {
            let mut cache = history.preview_cache.borrow_mut();
            cache
                .iter()
                .position(|entry| entry.hash == hash && entry.path == file.path)
                .and_then(|index| cache.remove(index))
                .map(|entry| {
                    let content = entry.content.clone();
                    cache.push_back(entry);
                    content
                })
        };
        if let Some(cached) = cached {
            log::debug!(
                "native history preview cache hit hash={hash} path={}",
                file.path
            );
            match cached {
                CachedHistoryPreviewContent::Diff(prepared) => self.apply_history_comparison(
                    self.ivars()
                        .active_workspace_id
                        .borrow()
                        .as_deref()
                        .unwrap_or_default(),
                    &hash,
                    &file.path,
                    request_id,
                    Ok(prepared),
                ),
                CachedHistoryPreviewContent::Binary(comparison) => self
                    .apply_history_bytes_comparison(
                        self.ivars()
                            .active_workspace_id
                            .borrow()
                            .as_deref()
                            .unwrap_or_default(),
                        &hash,
                        &file.path,
                        request_id,
                        Ok(comparison),
                    ),
                CachedHistoryPreviewContent::Unavailable(message) => {
                    self.show_history_comparison_error(&message)
                }
            }
            return;
        }
        history
            .empty
            .setStringValue(&NSString::from_str("Loading file diff…"));
        history.empty.setHidden(false);
        let Some(workspace_id) = self.ivars().active_workspace_id.borrow().clone() else {
            return;
        };
        let Some(handle) = self.ivars().git_handle.borrow().clone() else {
            return;
        };
        let Some(cancellation) = self.workspace_cancellation_token() else {
            return;
        };
        let Some(requests) = self.ivars().repository_requests.get() else {
            return;
        };
        let request = if is_changed_binary_preview_path(&file.path) {
            RepositoryRequest::LoadHistoryBytesComparison {
                workspace_id,
                handle,
                hash,
                path: file.path,
                request_id,
                cancellation,
            }
        } else {
            RepositoryRequest::LoadHistoryComparison {
                workspace_id,
                handle,
                hash,
                path: file.path,
                request_id,
                cancellation,
            }
        };
        if let Err(error) = requests.try_send(request) {
            history
                .empty
                .setStringValue(&NSString::from_str("Unable to queue file diff"));
            log::warn!("history comparison queue rejected request error={error}");
        }
    }

    fn apply_history_comparison(
        &self,
        workspace_id: &str,
        hash: &str,
        path: &str,
        request_id: u64,
        result: Result<PreparedDiff, String>,
    ) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id)
            || history.comparison_request_id.get() != request_id
            || history.selected_hash.borrow().as_deref() != Some(hash)
            || history.selected_file.borrow().as_deref() != Some(path)
        {
            return;
        }
        match result {
            Ok(prepared) => {
                self.cache_history_preview(
                    hash,
                    path,
                    CachedHistoryPreviewContent::Diff(prepared.clone()),
                );
                self.clear_history_binary_preview();
                history.loaded_binary_path.borrow_mut().take();
                history.loaded_diff_path.replace(Some(path.to_string()));
                history.diff.set_document(
                    path,
                    prepared.fingerprint,
                    prepared.document,
                    prepared.syntax,
                );
                history.diff.setHidden(!self.is_active_page("history"));
                history.empty.setHidden(true);
            }
            Err(error) => {
                history.loaded_diff_path.borrow_mut().take();
                if is_preview_limit_message(&error) {
                    self.cache_history_preview(
                        hash,
                        path,
                        CachedHistoryPreviewContent::Unavailable(error.clone()),
                    );
                }
                self.show_history_comparison_error(&error);
                log::warn!("native history comparison failed hash={hash} path={path}: {error}");
            }
        }
    }

    fn apply_history_bytes_comparison(
        &self,
        workspace_id: &str,
        hash: &str,
        path: &str,
        request_id: u64,
        result: Result<BytesComparison, String>,
    ) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id)
            || history.comparison_request_id.get() != request_id
            || history.selected_hash.borrow().as_deref() != Some(hash)
            || history.selected_file.borrow().as_deref() != Some(path)
        {
            return;
        }
        history.diff.setHidden(true);
        match result {
            Ok(comparison) => match self.populate_native_binary_comparison(
                &history.binary_preview,
                path,
                &comparison,
            ) {
                Ok(registrations) => {
                    self.cache_history_preview(
                        hash,
                        path,
                        CachedHistoryPreviewContent::Binary(comparison),
                    );
                    history.loaded_diff_path.borrow_mut().take();
                    history.loaded_binary_path.replace(Some(path.to_string()));
                    history.binary_font_registrations.replace(registrations);
                    history
                        .binary_preview
                        .setHidden(!self.is_active_page("history"));
                    history.empty.setHidden(true);
                    log::info!("native history binary preview applied hash={hash} path={path}");
                }
                Err(error) => {
                    history.loaded_binary_path.borrow_mut().take();
                    history.binary_font_registrations.borrow_mut().clear();
                    self.show_history_comparison_error(&error);
                    log::warn!(
                        "native history binary preview failed hash={hash} path={path}: {error}"
                    );
                }
            },
            Err(error) => {
                if is_preview_limit_message(&error) {
                    self.cache_history_preview(
                        hash,
                        path,
                        CachedHistoryPreviewContent::Unavailable(error.clone()),
                    );
                }
                history.loaded_diff_path.borrow_mut().take();
                history.loaded_binary_path.borrow_mut().take();
                history.binary_font_registrations.borrow_mut().clear();
                self.show_history_comparison_error(&error);
                log::warn!(
                    "native history binary comparison failed hash={hash} path={path}: {error}"
                );
            }
        }
    }

    fn cache_history_preview(&self, hash: &str, path: &str, content: CachedHistoryPreviewContent) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        let mut cache = history.preview_cache.borrow_mut();
        if let Some(index) = cache
            .iter()
            .position(|entry| entry.hash == hash && entry.path == path)
        {
            cache.remove(index);
        }
        cache.push_back(CachedHistoryPreview {
            hash: hash.to_string(),
            path: path.to_string(),
            content,
        });
        while cache.len() > HISTORY_PREVIEW_CACHE_CAPACITY {
            cache.pop_front();
        }
    }

    fn show_history_comparison_error(&self, message: &str) {
        let Some(history) = self.ivars().history.get() else {
            return;
        };
        history.diff.setHidden(true);
        self.clear_history_binary_preview();
        history.empty.setStringValue(&NSString::from_str(message));
        history.empty.setHidden(false);
    }

    fn begin_workspace_transition(&self, workspace_id: &str) {
        log::info!("native workspace transition started workspace={workspace_id}");
        if !self.ivars().terminal_sessions.borrow().is_empty() {
            log::info!("stopping workspace-scoped native terminal before workspace transition");
            self.shutdown_all_native_terminals();
        }
        self.cancel_commit_message_generation();
        for page_id in ["changes", "history", "files", "containers", "agents"] {
            self.set_page_badge(page_id, NativePageBadge::Indicator);
        }
        self.ivars()
            .active_workspace_id
            .replace(Some(workspace_id.to_string()));
        self.ivars().workspace_handle.replace(None);
        self.ivars().git_handle.replace(None);
        if let Some(settings) = self.ivars().commit_message_settings.get() {
            settings
                .workspace_request_id
                .set(settings.workspace_request_id.get().wrapping_add(1));
            settings.workspace_settings.borrow_mut().take();
            settings.workspace_loading.set(false);
            unsafe { settings.workspace_spinner.stopAnimation(None) };
            settings
                .workspace_status
                .setStringValue(&NSString::from_str(
                    "Loading the selected workspace’s Git settings…",
                ));
            self.update_workspace_settings_control_state();
        }
        self.clear_native_quick_actions("Loading workspace…");
        self.ivars().files_monitor.borrow_mut().take();
        self.ivars().repository_background_pull.borrow_mut().take();
        self.ivars().repository_monitor.borrow_mut().take();
        self.ivars().repository_snapshot.replace(None);
        self.ivars().repository_loading.set(true);
        if let Some(agents) = self.ivars().agents.get() {
            agents
                .generation
                .set(agents.generation.get().wrapping_add(1));
        }
        if let Some(commands) = self.ivars().agent_commands.get()
            && let Err(error) = commands.try_send(NativeAgentCommand::Reset)
        {
            log::warn!("native Codex workspace reset queue failed: {error}");
        }
        self.reset_native_agent_ui();
        self.ivars().changes_filter_query.borrow_mut().clear();
        self.ivars().changes_search_visible.set(false);
        if let Some(search) = self.ivars().changes_search.get() {
            search.setStringValue(&NSString::new());
        }
        if let Some(popover) = self.ivars().branch_popover.get() {
            popover.close();
        }
        if let Some(popover) = self.ivars().author_popover.get() {
            popover.close();
        }
        if let Some(popover) = self.ivars().author_warning_popover.borrow_mut().take() {
            popover.close();
        }
        self.clear_changed_files("Loading workspace…");
        self.reset_history("Loading workspace…");
        self.clear_font_preview();
        self.clear_sqlite_preview();
        if let Some(files) = self.ivars().files.get() {
            files.generation.set(files.generation.get().wrapping_add(1));
            files
                .preview_request_id
                .set(files.preview_request_id.get().wrapping_add(1));
            files.rows.borrow_mut().clear();
            files.dirty.set(false);
            files.expanded.borrow_mut().clear();
            files.selected_path.borrow_mut().take();
            files
                .drop_hover_generation
                .set(files.drop_hover_generation.get().wrapping_add(1));
            files.drop_hover_path.borrow_mut().take();
            files.loaded_text_path.borrow_mut().take();
            files.loaded_text_signature.borrow_mut().take();
            files.text_buffer.borrow_mut().clear();
            files.text_selection.set(NSRange::new(0, 0));
            files.text_editable.set(false);
            files.preview_code.clear_completions();
            files.pending_text_selection.borrow_mut().take();
            files
                .text_edit_generation
                .set(files.text_edit_generation.get().wrapping_add(1));
            files.text_dirty.set(false);
            files.text_save_in_progress.set(false);
            files.preview_text.setEditable(false);
            files.table.reloadData();
            files.status.setHidden(false);
            files.mutation_in_progress.set(false);
            files
                .status
                .setStringValue(&NSString::from_str("Loading workspace…"));
            files
                .title
                .setStringValue(&NSString::from_str("Select a file"));
            files.metadata_base.borrow_mut().clear();
            files.metadata.setStringValue(&NSString::new());
            files.empty.setStringValue(&NSString::from_str(
                "Select a file or folder from the workspace tree.",
            ));
            files.empty.setHidden(false);
            files.preview_scroll.setHidden(true);
            files.preview_image.setHidden(true);
            files.preview_image.clear_image();
            files.preview_pdf.setHidden(true);
            // SAFETY: Workspace transitions run on AppKit's main thread.
            unsafe { files.preview_pdf.setDocument(None) };
            self.clear_csv_table_preview();
            files.preview_web_mode.set(NativeWebPreviewMode::Hidden);
            files.preview_web.setHidden(true);
            files.preview_divider.setHidden(true);
            // SAFETY: Workspace transitions run on AppKit's main thread.
            unsafe { files.preview_web.stopLoading() };
            unsafe { files.preview_spinner.stopAnimation(None) };
            files.preview_spinner.setHidden(true);
        }
        if let Some(containers) = self.ivars().containers.get() {
            containers
                .generation
                .set(containers.generation.get().wrapping_add(1));
            containers
                .detail_request_id
                .set(containers.detail_request_id.get().wrapping_add(1));
            containers
                .action_request_id
                .set(containers.action_request_id.get().wrapping_add(1));
            containers.rows.borrow_mut().clear();
            containers.expanded_groups.borrow_mut().clear();
            containers.selected_id.borrow_mut().take();
            containers.selected_group_key.borrow_mut().take();
            containers.query.borrow_mut().clear();
            containers.search.setStringValue(&NSString::new());
            containers.table.reloadData();
            containers.scroll.setHidden(true);
            containers.dirty.set(true);
            containers.loading.set(false);
            containers.action_in_progress.set(false);
            unsafe { containers.spinner.stopAnimation(None) };
            containers.spinner.setHidden(true);
            containers.status.setHidden(false);
            containers
                .status
                .setStringValue(&NSString::from_str("Loading workspace…"));
            containers
                .title
                .setStringValue(&NSString::from_str("Containers"));
            containers.subtitle.setStringValue(&NSString::new());
            containers.details_scroll.setHidden(true);
            containers.inspect_code.setHidden(true);
            containers.inspect.setHidden(true);
            containers.empty.setStringValue(&NSString::from_str(
                "Select a container or Compose project.",
            ));
            containers.empty.setHidden(false);
            for button in [
                &containers.logs,
                &containers.inspect,
                &containers.shell,
                &containers.start,
                &containers.stop,
                &containers.restart,
                &containers.remove,
            ] {
                button.setEnabled(false);
            }
        }
        self.set_repository_controls_unavailable("Loading workspace…");
        self.update_commit_composer_state();
        self.layout_sidebar();
    }

    fn request_repository_load(&self, workspace: craic_config::ConfiguredWorkspace) {
        let workspace_id = workspace.selection_id();
        let Some(cancellation) = self.workspace_cancellation_token() else {
            return;
        };
        let Some(requests) = self.ivars().repository_requests.get() else {
            let message = "Repository service is unavailable.".to_string();
            log::warn!("repository load ignored because repository service is unavailable");
            self.apply_repository_snapshot(&workspace_id, None, Err(message));
            return;
        };
        if let Err(error) = requests.try_send(RepositoryRequest::Load {
            workspace,
            cancellation,
        }) {
            let message = format!("Unable to queue workspace load: {error}");
            log::warn!("repository load queue rejected request error={error}");
            self.apply_repository_snapshot(&workspace_id, None, Err(message));
        }
    }

    fn apply_repository_snapshot(
        &self,
        workspace_id: &str,
        handle: Option<Arc<GitRepoHandle>>,
        result: Result<WorkspaceSnapshot, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            log::debug!("discarding stale repository snapshot workspace={workspace_id}");
            return;
        }
        let first_workspace_snapshot = self.ivars().workspace_handle.borrow().is_none();
        self.ivars().repository_loading.set(false);
        if result.is_ok() {
            self.ivars().workspace_handle.replace(handle.clone());
            self.request_native_quick_actions();
        }
        match result {
            Ok(WorkspaceSnapshot::Repository(snapshot)) => {
                let history_changed = self
                    .ivars()
                    .repository_snapshot
                    .borrow()
                    .as_ref()
                    .and_then(|previous| previous.history_head.as_ref())
                    != snapshot.history_head.as_ref();
                if history_changed {
                    self.reset_history("Loading commits...");
                }
                self.ivars().file_preview_cache.borrow_mut().clear();
                self.ivars().git_handle.replace(handle.clone());
                if self.ivars().repository_monitor.borrow().is_none()
                    && let (Some(handle), Some(requests)) =
                        (handle, self.ivars().repository_requests.get().cloned())
                {
                    let Some(cancellation) = self.workspace_cancellation_token() else {
                        return;
                    };
                    let monitored_workspace = workspace_id.to_string();
                    let monitored_handle = handle.clone();
                    let listener: ChangeListener = Arc::new(move || {
                        if let Err(error) = requests.try_send(RepositoryRequest::Refresh {
                            workspace_id: monitored_workspace.clone(),
                            handle: monitored_handle.clone(),
                            cancellation: cancellation.clone(),
                        }) {
                            log::debug!(
                                "native repository monitor coalesced refresh workspace={} error={error}",
                                monitored_workspace
                            );
                        }
                    });
                    self.ivars()
                        .repository_monitor
                        .replace(Some(handle.add_on_change_listener(listener.clone())));
                    self.ivars()
                        .repository_background_pull
                        .replace(Some(handle.schedule_background_pull_loop(Some(listener))));
                    log::info!(
                        "native repository monitor and background pull subscribed workspace={workspace_id}"
                    );
                }
                self.update_changed_files_snapshot(&snapshot);
                self.ivars()
                    .repository_snapshot
                    .replace(Some(snapshot.clone()));
                self.restore_changes_page_badge();
                self.configure_repository_controls(&snapshot, false);
                self.refresh_changed_file_results();
                self.update_commit_composer_state();
                if let Some(path) = self.ivars().selected_change_path.borrow().clone() {
                    self.request_file_comparison(path);
                }
                if self.is_active_page("changes")
                    && let Some(content_empty) = self.ivars().content_empty.get()
                {
                    content_empty.setStringValue(&NSString::from_str(
                        if snapshot.changed_files.is_empty() {
                            "No changes"
                        } else {
                            "Select a changed file to review its diff"
                        },
                    ));
                }
                log::info!(
                    "native repository snapshot applied workspace={} branch={} changes={}",
                    workspace_id,
                    snapshot.branch,
                    snapshot.changed_files.len()
                );
                if self.is_active_page("history")
                    && (history_changed
                        || self
                            .ivars()
                            .history
                            .get()
                            .is_some_and(|history| history.commits.borrow().is_empty()))
                {
                    self.request_history_page(true);
                }
                if self.is_active_page("files") {
                    self.request_files_tree();
                }
                if self.is_active_page("containers") {
                    self.request_containers();
                }
            }
            Ok(WorkspaceSnapshot::NonRepository { name }) => {
                self.ivars().repository_background_pull.borrow_mut().take();
                self.ivars().repository_monitor.borrow_mut().take();
                self.ivars().git_handle.replace(None);
                self.ivars().repository_snapshot.replace(None);
                self.set_page_badge("changes", NativePageBadge::None);
                self.set_page_badge("history", NativePageBadge::None);
                self.clear_changed_files("No repository content");
                self.reset_history("No repository content");
                self.set_repository_controls_unavailable("Not a Git repository.");
                self.update_commit_composer_state();
                if self.is_active_page("files") {
                    self.request_files_tree();
                }
                if self.is_active_page("containers") {
                    self.request_containers();
                }
                if self.is_active_page("changes")
                    && let Some(content_empty) = self.ivars().content_empty.get()
                {
                    content_empty.setStringValue(&NSString::from_str("No repository content"));
                }
                log::info!("native non-repository workspace applied workspace={name}");
            }
            Err(error) => {
                self.ivars().repository_background_pull.borrow_mut().take();
                self.ivars().repository_monitor.borrow_mut().take();
                self.ivars().files_monitor.borrow_mut().take();
                self.ivars().workspace_handle.replace(None);
                self.ivars().git_handle.replace(None);
                self.ivars().repository_snapshot.replace(None);
                self.clear_native_quick_actions("Quick Actions are unavailable.");
                for page_id in ["changes", "history", "files", "containers"] {
                    self.set_page_badge(page_id, NativePageBadge::None);
                }
                self.clear_changed_files("Unable to load workspace");
                self.reset_history("Unable to load workspace");
                self.set_repository_controls_unavailable(&error);
                self.update_commit_composer_state();
                if let Some(files) = self.ivars().files.get() {
                    files.loading.set(false);
                    unsafe { files.spinner.stopAnimation(None) };
                    files.spinner.setHidden(true);
                    files.status.setHidden(false);
                    files
                        .status
                        .setStringValue(&NSString::from_str("Unable to load workspace"));
                }
                if let Some(containers) = self.ivars().containers.get() {
                    containers.loading.set(false);
                    containers.scroll.setHidden(true);
                    unsafe { containers.spinner.stopAnimation(None) };
                    containers.spinner.setHidden(true);
                    containers.status.setHidden(false);
                    containers
                        .status
                        .setStringValue(&NSString::from_str("Unable to load workspace"));
                }
                if self.is_active_page("changes")
                    && let Some(content_empty) = self.ivars().content_empty.get()
                {
                    content_empty.setStringValue(&NSString::from_str("Unable to load workspace"));
                }
                log::warn!("native repository snapshot failed workspace={workspace_id}: {error}");
            }
        }
        if first_workspace_snapshot
            && self
                .ivars()
                .commit_message_settings
                .get()
                .is_some_and(|settings| settings.window.isVisible())
        {
            self.request_workspace_settings_load();
        }
    }

    fn update_commit_composer_state(&self) {
        let Some(composer) = self.ivars().commit_composer.get() else {
            return;
        };
        let snapshot = self.ivars().repository_snapshot.borrow();
        let mut selected_files = self
            .ivars()
            .checked_change_paths
            .borrow()
            .iter()
            .cloned()
            .collect::<Vec<_>>();
        selected_files.sort();
        let has_selected_files = !selected_files.is_empty();
        let repository_available = self.ivars().git_handle.borrow().is_some();
        composer.set_branch(snapshot.as_ref().map(|snapshot| snapshot.branch.as_str()));
        let file_signature = snapshot
            .as_ref()
            .map(|snapshot| {
                snapshot
                    .changed_files
                    .iter()
                    .map(|file| (file.path.clone(), file.status.clone()))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let default_summary = default_commit_summary(&selected_files, &file_signature);
        let avatar_source = snapshot.as_ref().and_then(|snapshot| {
            snapshot
                .github_avatar_url
                .as_ref()
                .map(|url| (format!("url:{url}"), AvatarSource::Url(url.to_string())))
                .or_else(|| {
                    snapshot.user_email.as_ref().and_then(|email| {
                        let email = email.trim();
                        (!email.is_empty()).then(|| {
                            (
                                format!("email:{}", email.to_ascii_lowercase()),
                                AvatarSource::Email(email.to_string()),
                            )
                        })
                    })
                })
        });
        let avatar_key = avatar_source.as_ref().map(|(key, _)| key.clone());
        let avatar_image = avatar_key
            .as_deref()
            .and_then(|key| self.ivars().avatar_images.borrow().get(key).cloned());
        self.ivars()
            .commit_avatar_source
            .replace(avatar_key.clone());
        let author_warning = snapshot
            .as_ref()
            .and_then(RepositorySnapshot::remote_author_warning_text);
        composer.set_author(
            snapshot
                .as_ref()
                .and_then(|snapshot| snapshot.user_name.as_deref()),
            avatar_image.as_deref(),
            author_warning.as_deref(),
        );
        drop(snapshot);
        if avatar_image.is_none()
            && let Some((cache_key, source)) = avatar_source
        {
            self.request_avatar(cache_key, source);
        }
        composer.set_repository_available(repository_available);
        composer.set_has_selected_files(has_selected_files);
        composer.set_default_summary(default_summary);
        composer.set_can_generate(true);
    }

    fn cancel_commit_message_generation(&self) {
        if let Some(cancellation) = self.ivars().commit_message_cancellation.borrow_mut().take() {
            cancellation.cancel();
        }
        self.ivars().commit_message_generation_id.set(
            self.ivars()
                .commit_message_generation_id
                .get()
                .wrapping_add(1),
        );
        if let Some(composer) = self.ivars().commit_composer.get() {
            composer.set_generating(false);
        }
        log::info!("native commit message generation cancel requested");
    }

    fn apply_generated_commit_message(
        &self,
        workspace_id: &str,
        request_id: u64,
        provider_label: &str,
        result: Result<CommitMessageDraft, String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id)
            || self.ivars().commit_message_generation_id.get() != request_id
        {
            log::debug!(
                "discarding stale commit message generation workspace={workspace_id} request_id={request_id}"
            );
            return;
        }
        self.ivars().commit_message_cancellation.borrow_mut().take();
        let Some(composer) = self.ivars().commit_composer.get() else {
            return;
        };
        composer.set_generating(false);
        match result {
            Ok(draft) => {
                composer.set_message(&draft.summary, &draft.description);
                log::info!(
                    "native commit message generated provider={} request_id={request_id}",
                    provider_label
                );
            }
            Err(error) if is_canceled_error(&error) => {
                log::info!("native commit message generation canceled request_id={request_id}");
            }
            Err(error) => {
                self.present_path_action_error("Generate Commit Message Failed", &error);
                log::warn!(
                    "native commit message generation failed request_id={request_id}: {error}"
                );
            }
        }
    }

    fn finish_commit(&self, workspace_id: &str, result: &Result<String, String>) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        if let Some(composer) = self.ivars().commit_composer.get() {
            composer.set_committing(false);
            match result {
                Ok(message) => {
                    composer.set_message("", "");
                    composer.show_completion(message);
                }
                Err(_) => self.update_commit_composer_state(),
            }
        }
        if let Err(error) = result {
            let alert = NSAlert::new(self.mtm());
            alert.setMessageText(&NSString::from_str("Commit Failed"));
            alert.setInformativeText(&NSString::from_str(error));
            alert.addButtonWithTitle(&NSString::from_str("OK"));
            if let Some(window) = self.ivars().window.get() {
                alert.beginSheetModalForWindow_completionHandler(window, None);
            }
        }
    }

    fn update_changed_files_snapshot(&self, snapshot: &RepositorySnapshot) {
        let previous_paths = self
            .ivars()
            .repository_snapshot
            .borrow()
            .as_ref()
            .map(|previous| {
                previous
                    .changed_files
                    .iter()
                    .map(|file| file.path.clone())
                    .collect::<HashSet<_>>()
            })
            .unwrap_or_default();
        let next_paths = snapshot
            .changed_files
            .iter()
            .map(|file| file.path.clone())
            .collect::<HashSet<_>>();
        let mut checked = self.ivars().checked_change_paths.borrow_mut();
        checked.retain(|path| next_paths.contains(path.as_str()));
        for path in &next_paths {
            if !previous_paths.contains(path) {
                checked.insert(path.clone());
            }
        }
        drop(checked);

        let selection_is_valid = self
            .ivars()
            .selected_change_path
            .borrow()
            .as_ref()
            .is_some_and(|path| next_paths.contains(path.as_str()));
        if !selection_is_valid {
            self.ivars().selected_change_path.borrow_mut().take();
            self.ivars().loaded_diff_path.borrow_mut().take();
            self.ivars().loaded_image_path.borrow_mut().take();
            self.ivars().diff_loading_request_id.set(None);
            self.ivars()
                .diff_request_id
                .set(self.ivars().diff_request_id.get().wrapping_add(1));
            if let Some(diff_view) = self.ivars().diff_view.get() {
                diff_view.clear();
                diff_view.setHidden(true);
            }
            if let Some(image) = self.ivars().image_preview.get() {
                image.setImage(None);
                image.setHidden(true);
            }
            self.clear_changed_binary_preview();
            if let Some(spinner) = self.ivars().diff_spinner.get() {
                // SAFETY: The retained progress indicator is animated on the AppKit main thread.
                unsafe { spinner.stopAnimation(None) };
                spinner.setHidden(true);
            }
            if self.is_active_page("changes")
                && let Some(empty) = self.ivars().content_empty.get()
            {
                empty.setStringValue(&NSString::from_str(if snapshot.changed_files.is_empty() {
                    "No local changes"
                } else {
                    "Select a changed file to review its diff"
                }));
                empty.setHidden(false);
            }
        }
    }

    fn clear_changed_files(&self, message: &str) {
        self.hide_repository_home();
        self.ivars().selected_change_path.borrow_mut().take();
        self.ivars().checked_change_paths.borrow_mut().clear();
        self.ivars().loaded_diff_path.borrow_mut().take();
        self.ivars().loaded_image_path.borrow_mut().take();
        self.ivars().file_preview_cache.borrow_mut().clear();
        self.ivars().diff_loading_request_id.set(None);
        self.ivars()
            .diff_request_id
            .set(self.ivars().diff_request_id.get().wrapping_add(1));
        if let Some(list) = self.ivars().changes_list.get() {
            let subviews = list.subviews();
            for index in 0..subviews.count() {
                subviews.objectAtIndex(index).removeFromSuperview();
            }
        }
        if let Some(diff_view) = self.ivars().diff_view.get() {
            diff_view.clear();
            diff_view.setHidden(true);
        }
        if let Some(image) = self.ivars().image_preview.get() {
            image.setImage(None);
            image.setHidden(true);
        }
        self.clear_changed_binary_preview();
        if let Some(spinner) = self.ivars().diff_spinner.get() {
            // SAFETY: The retained progress indicator is animated on the AppKit main thread.
            unsafe { spinner.stopAnimation(None) };
            spinner.setHidden(true);
        }
        if self.is_active_page("changes")
            && let Some(empty) = self.ivars().content_empty.get()
        {
            empty.setStringValue(&NSString::from_str(message));
            empty.setHidden(false);
        }
        self.refresh_selection_header();
    }

    fn configure_repository_controls(&self, snapshot: &RepositorySnapshot, running: bool) {
        if let Some(branch) = self.ivars().branch_button.get() {
            branch.setTitle(&NSString::from_str(if snapshot.branch.is_empty() {
                "Branch"
            } else {
                &snapshot.branch
            }));
            branch.setEnabled(!running && !snapshot.branch.is_empty());
        }
        if self
            .ivars()
            .branch_popover
            .get()
            .is_some_and(|popover| popover.isShown())
        {
            let filter = self
                .ivars()
                .branch_search
                .get()
                .map(|search| search.stringValue().to_string())
                .unwrap_or_default();
            self.update_branch_footer();
            self.refresh_branch_results(&filter);
        }
        let Some(fetch) = self.ivars().fetch_button.get() else {
            return;
        };
        let remote = snapshot.remote_name.as_deref().unwrap_or("remote");
        let (label, symbol) = if !snapshot.has_upstream {
            if snapshot.remote_name.is_some() {
                ("Publish branch".to_string(), "paperplane")
            } else {
                ("Publish repository".to_string(), "paperplane")
            }
        } else if snapshot.behind > 0 && snapshot.ahead > 0 {
            (format!("Pull & Push {remote}"), "arrow.up.arrow.down")
        } else if snapshot.behind > 0 {
            (format!("Pull {remote}"), "arrow.down")
        } else if snapshot.ahead > 0 {
            (format!("Push {remote}"), "arrow.up")
        } else {
            (format!("Fetch {remote}"), "arrow.triangle.2.circlepath")
        };
        fetch.setTitle(&NSString::from_str(&format!("\u{2002}{label}")));
        if let Some(image) = NSImage::imageWithSystemSymbolName_accessibilityDescription(
            &NSString::from_str(symbol),
            Some(&NSString::from_str(&label)),
        ) {
            fetch.setImage(Some(&image));
        }
        self.set_fetch_spinner_running(running);
        fetch.setToolTip(Some(&NSString::from_str(&label)));
        fetch.setEnabled(
            !running && (snapshot.remote_name.is_some() || !snapshot.branch.is_empty()),
        );
        if self.is_active_page("changes") && self.ivars().selected_change_path.borrow().is_none() {
            self.update_repository_home(snapshot, running);
        }
    }

    fn set_repository_action_progress(&self, workspace_id: &str, progress: &str) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        if let Some(fetch) = self.ivars().fetch_button.get() {
            let progress = progress.trim();
            if !progress.is_empty() {
                fetch.setTitle(&NSString::from_str(&format!("\u{2003}\u{2003}{progress}")));
                fetch.setToolTip(Some(&NSString::from_str(progress)));
            }
            self.set_fetch_spinner_running(true);
            fetch.setEnabled(false);
        }
        if let Some(action) = self.ivars().content_home_action.get()
            && !action.isHidden()
        {
            action.setTitle(&NSString::from_str("Working…"));
            action.setEnabled(false);
        }
    }

    fn repository_action_failed(&self, workspace_id: &str, title: &str, message: &str) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        if let Some(snapshot) = self.ivars().repository_snapshot.borrow().clone() {
            self.configure_repository_controls(&snapshot, false);
        }
        if let Some(fetch) = self.ivars().fetch_button.get() {
            fetch.setToolTip(Some(&NSString::from_str(message)));
        }
        self.present_path_action_error(title, message);
        log::warn!("native git action failed workspace={workspace_id}: {message}");
    }

    fn show_local_changes_overwritten_dialog(
        &self,
        workspace_id: String,
        handle: Arc<GitRepoHandle>,
        snapshot: RepositorySnapshot,
        action: NativeRemoteAction,
        files: Vec<String>,
    ) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(&workspace_id) {
            return;
        }
        self.configure_repository_controls(&snapshot, false);
        let Some(window) = self.ivars().window.get() else {
            return;
        };
        let alert = NSAlert::new(self.mtm());
        alert.setMessageText(&NSString::from_str("Local Changes Would Be Overwritten"));
        alert.setInformativeText(&NSString::from_str(&local_changes_overwritten_body(
            action, &snapshot, &files,
        )));
        alert.addButtonWithTitle(&NSString::from_str("Stash Changes and Continue"));
        alert.addButtonWithTitle(&NSString::from_str("Close"));
        alert.setAlertStyle(NSAlertStyle::Warning);
        let delegate = self.retain();
        let completion = RcBlock::new(move |response| {
            if response != NSAlertFirstButtonReturn
                || delegate.ivars().active_workspace_id.borrow().as_deref()
                    != Some(workspace_id.as_str())
            {
                return;
            }
            let Some(requests) = delegate.ivars().repository_requests.get() else {
                delegate.repository_action_failed(
                    &workspace_id,
                    "Stash Failed",
                    "The repository service is unavailable.",
                );
                return;
            };
            delegate.set_repository_action_progress(&workspace_id, "Stashing changes…");
            if let Err(error) = requests.try_send(RepositoryRequest::RunGitAction {
                workspace_id: workspace_id.clone(),
                handle: handle.clone(),
                snapshot: snapshot.clone(),
                action,
                stash_before: true,
            }) {
                delegate.repository_action_failed(
                    &workspace_id,
                    "Stash Failed",
                    &format!("The stash request could not be queued: {error}"),
                );
            }
        });
        alert.beginSheetModalForWindow_completionHandler(window, Some(&completion));
    }

    fn set_branch_action_progress(&self, workspace_id: &str, label: &str) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        if let Some(branch) = self.ivars().branch_button.get() {
            branch.setTitle(&NSString::from_str(label));
            branch.setEnabled(false);
        }
        if let Some(fetch) = self.ivars().fetch_button.get() {
            fetch.setEnabled(false);
        }
    }

    fn branch_action_failed(&self, workspace_id: &str, message: &str) {
        if self.ivars().active_workspace_id.borrow().as_deref() != Some(workspace_id) {
            return;
        }
        if let Some(snapshot) = self.ivars().repository_snapshot.borrow().clone() {
            self.configure_repository_controls(&snapshot, false);
        }
        let Some(window) = self.ivars().window.get() else {
            return;
        };
        let alert = NSAlert::new(self.mtm());
        alert.setMessageText(&NSString::from_str("Branch Operation Failed"));
        alert.setInformativeText(&NSString::from_str(message));
        alert.addButtonWithTitle(&NSString::from_str("OK"));
        alert.beginSheetModalForWindow_completionHandler(window, None);
        log::warn!("native branch action failed workspace={workspace_id}: {message}");
    }

    fn set_repository_controls_unavailable(&self, message: &str) {
        if let Some(branch) = self.ivars().branch_button.get() {
            branch.setTitle(&NSString::from_str("Branch"));
            branch.setEnabled(false);
        }
        if let Some(fetch) = self.ivars().fetch_button.get() {
            fetch.setTitle(&NSString::from_str("\u{2002}Fetch remote"));
            self.set_fetch_spinner_running(false);
            if let Some(image) = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                &NSString::from_str("arrow.triangle.2.circlepath"),
                Some(&NSString::from_str("Fetch remote")),
            ) {
                fetch.setImage(Some(&image));
            }
            fetch.setEnabled(false);
            fetch.setToolTip(Some(&NSString::from_str(message)));
        }
    }

    fn set_fetch_spinner_running(&self, running: bool) {
        let Some(spinner) = self.ivars().fetch_spinner.get() else {
            return;
        };
        if running {
            if let Some(fetch) = self.ivars().fetch_button.get() {
                fetch.setImage(None);
            }
            // SAFETY: The spinner is retained by the delegate and animated on AppKit's main thread.
            unsafe { spinner.startAnimation(None) };
        } else {
            // SAFETY: The spinner is retained by the delegate and animated on AppKit's main thread.
            unsafe { spinner.stopAnimation(None) };
        }
    }

    fn show_open_workspace_panel(&self) {
        let Some(requests) = self.ivars().frontend_requests.get() else {
            log::warn!("workspace picker ignored because the UI effect bridge is unavailable");
            return;
        };
        if let Err(error) = requests.try_send(FrontendRequest::OpenWorkspace) {
            log::warn!("workspace picker request queue rejected request error={error}");
        }
    }

    fn request_discard_confirmation(&self, paths: Vec<String>, heading: String, message: String) {
        let Some(requests) = self.ivars().frontend_requests.get() else {
            self.changes_operation_failed(
                "Discard Failed",
                "The native confirmation service is unavailable",
            );
            return;
        };
        if let Err(error) = requests.try_send(FrontendRequest::ConfirmDiscard {
            paths,
            heading,
            message,
        }) {
            self.changes_operation_failed(
                "Discard Failed",
                &format!("The confirmation request could not be queued: {error}"),
            );
        }
    }

    fn apply_repository_completion(&self, completion: RepositoryCompletion) {
        match completion {
            RepositoryCompletion::Snapshot {
                workspace_id,
                handle,
                result,
            } => self.apply_repository_snapshot(&workspace_id, handle, result),
            RepositoryCompletion::ActionProgress {
                workspace_id,
                message,
            } => self.set_repository_action_progress(&workspace_id, &message),
            RepositoryCompletion::ActionFailed {
                workspace_id,
                title,
                message,
            } => self.repository_action_failed(&workspace_id, title, &message),
            RepositoryCompletion::ActionNeedsStash {
                workspace_id,
                handle,
                snapshot,
                action,
                files,
            } => self.show_local_changes_overwritten_dialog(
                workspace_id,
                handle,
                snapshot,
                action,
                files,
            ),
            RepositoryCompletion::ActionFinished {
                workspace_id,
                handle,
                result,
                message,
            } => {
                let current_workspace = self.ivars().active_workspace_id.borrow().as_deref()
                    == Some(workspace_id.as_str());
                let succeeded = result.is_ok();
                self.apply_repository_snapshot(&workspace_id, Some(handle), result);
                if current_workspace && succeeded {
                    self.show_native_toast(
                        message
                            .as_deref()
                            .map(str::trim)
                            .filter(|message| !message.is_empty())
                            .unwrap_or("Git operation completed."),
                    );
                }
            }
            RepositoryCompletion::QuickActions {
                workspace_id,
                generation,
                result,
            } => self.apply_native_quick_actions(&workspace_id, generation, result),
            RepositoryCompletion::QuickActionConfigurationSaved {
                workspace_id,
                result,
            } => {
                if self.ivars().active_workspace_id.borrow().as_deref() == Some(&workspace_id)
                    && let Err(error) = result
                {
                    self.present_path_action_error(
                        "Unable to Save Quick Actions",
                        &format!("The Quick Actions strip will work for this session, but could not be saved: {error}"),
                    );
                }
            }
            RepositoryCompletion::BranchProgress {
                workspace_id,
                message,
            } => self.set_branch_action_progress(&workspace_id, &message),
            RepositoryCompletion::BranchFailed {
                workspace_id,
                message,
            } => self.branch_action_failed(&workspace_id, &message),
            RepositoryCompletion::BranchFinished {
                workspace_id,
                handle,
                result,
                message,
            } => {
                let current_workspace = self.ivars().active_workspace_id.borrow().as_deref()
                    == Some(workspace_id.as_str());
                let succeeded = result.is_ok();
                self.apply_repository_snapshot(&workspace_id, Some(handle), result);
                if current_workspace && succeeded {
                    self.show_native_toast(message.trim());
                }
            }
            RepositoryCompletion::FileComparison {
                workspace_id,
                path,
                request_id,
                result,
            } => self.apply_file_comparison(&workspace_id, &path, request_id, result),
            RepositoryCompletion::FileBytesComparison {
                workspace_id,
                path,
                request_id,
                result,
            } => self.apply_file_bytes_comparison(&workspace_id, &path, request_id, result),
            RepositoryCompletion::HistoryPage {
                workspace_id,
                generation,
                result,
            } => self.apply_history_page(&workspace_id, generation, result),
            RepositoryCompletion::HistoryCommit {
                workspace_id,
                hash,
                request_id,
                result,
            } => self.apply_history_commit(&workspace_id, &hash, request_id, result),
            RepositoryCompletion::HistoryComparison {
                workspace_id,
                hash,
                path,
                request_id,
                result,
            } => self.apply_history_comparison(&workspace_id, &hash, &path, request_id, result),
            RepositoryCompletion::HistoryBytesComparison {
                workspace_id,
                hash,
                path,
                request_id,
                result,
            } => {
                self.apply_history_bytes_comparison(&workspace_id, &hash, &path, request_id, result)
            }
            RepositoryCompletion::FilesTree {
                workspace_id,
                generation,
                result,
            } => self.apply_files_tree(&workspace_id, generation, result),
            RepositoryCompletion::WorkspaceFile {
                workspace_id,
                path,
                request_id,
                result,
            } => self.apply_workspace_file(&workspace_id, &path, request_id, result),
            RepositoryCompletion::WorkspaceFolder {
                workspace_id,
                path,
                request_id,
                result,
            } => self.apply_workspace_folder(&workspace_id, &path, request_id, result),
            RepositoryCompletion::WorkspaceSqliteSchema {
                workspace_id,
                path,
                request_id,
                result,
            } => self.apply_workspace_sqlite_schema(&workspace_id, &path, request_id, result),
            RepositoryCompletion::WorkspaceSqlitePage {
                workspace_id,
                path,
                generation,
                result,
            } => self.apply_workspace_sqlite_page(&workspace_id, &path, generation, result),
            RepositoryCompletion::WorkspaceFilesChanged { workspace_id } => {
                self.workspace_files_changed(&workspace_id)
            }
            RepositoryCompletion::FileMutationFinished {
                workspace_id,
                access,
                mutation,
                allow_sudo_retry,
                result,
            } => {
                self.finish_file_mutation(&workspace_id, access, mutation, allow_sudo_retry, result)
            }
            RepositoryCompletion::FileDownloadFinished {
                workspace_id,
                access,
                source,
                destination,
                allow_sudo_retry,
                result,
            } => self.finish_workspace_file_download(
                &workspace_id,
                access,
                source,
                destination,
                allow_sudo_retry,
                result,
            ),
            RepositoryCompletion::FileSudoAuthorized {
                workspace_id,
                access,
                retry,
                result,
            } => self.apply_file_sudo_authorization(&workspace_id, access, retry, result),
            RepositoryCompletion::WorkspaceFileSaved {
                workspace_id,
                access,
                path,
                text,
                expected_signature,
                edit_generation,
                allow_sudo_retry,
                result,
            } => self.finish_workspace_file_save(
                &workspace_id,
                access,
                path,
                text,
                expected_signature,
                edit_generation,
                allow_sudo_retry,
                result,
            ),
            RepositoryCompletion::WorkspaceTextHighlighted {
                workspace_id,
                path,
                edit_generation,
                result,
            } => {
                self.apply_workspace_text_highlights(&workspace_id, &path, edit_generation, result)
            }
            RepositoryCompletion::Containers {
                workspace_id,
                generation,
                result,
            } => self.apply_containers(&workspace_id, generation, result),
            RepositoryCompletion::ContainerDetail {
                workspace_id,
                container_id,
                request_id,
                kind,
                result,
            } => {
                self.apply_container_detail(&workspace_id, &container_id, request_id, kind, result)
            }
            RepositoryCompletion::ContainerActionFinished {
                workspace_id,
                request_id,
                result,
            } => self.finish_container_action(&workspace_id, request_id, result),
            RepositoryCompletion::Avatar { cache_key, result } => {
                self.apply_avatar(&cache_key, result)
            }
            RepositoryCompletion::CommitAuthors {
                workspace_id,
                result,
            } => self.apply_commit_author_options(&workspace_id, result),
            RepositoryCompletion::AgentFileLinkResolved {
                workspace_id,
                line,
                column,
                result,
            } => self.apply_agent_file_link(&workspace_id, line, column, result),
            RepositoryCompletion::AgentImage {
                workspace_id,
                generation,
                item_id,
                source,
                result,
            } => self.apply_native_agent_transcript_image(
                &workspace_id,
                generation,
                &item_id,
                source,
                result,
            ),
            RepositoryCompletion::CommitAuthorFinished {
                workspace_id,
                handle,
                result,
            } => self.finish_commit_author(&workspace_id, handle, result),
            RepositoryCompletion::CommitFinished {
                workspace_id,
                handle,
                snapshot,
                result,
            } => {
                if let Some(snapshot) = snapshot {
                    self.apply_repository_snapshot(&workspace_id, handle, snapshot);
                }
                self.finish_commit(&workspace_id, &result);
            }
            RepositoryCompletion::CommitMessageGenerated {
                workspace_id,
                request_id,
                provider_label,
                result,
            } => self.apply_generated_commit_message(
                &workspace_id,
                request_id,
                &provider_label,
                result,
            ),
            RepositoryCompletion::CommitMessageSettingsLoaded {
                request_id,
                provider_id,
                model,
            } => self.apply_commit_message_settings(request_id, provider_id, model),
            RepositoryCompletion::CommitMessageModelsLoaded {
                request_id,
                provider_id,
                selected_model,
                result,
            } => self.apply_commit_message_models(request_id, provider_id, selected_model, result),
            RepositoryCompletion::CommitMessageSettingsFailed { message } => {
                self.set_commit_message_settings_error(&message)
            }
            RepositoryCompletion::WorkspaceSettingsLoaded {
                workspace_id,
                request_id,
                result,
            } => self.apply_workspace_settings(&workspace_id, request_id, result),
            RepositoryCompletion::WorkspaceSettingsSaved {
                workspace_id,
                request_id,
                handle,
                result,
            } => self.finish_workspace_settings_save(&workspace_id, request_id, handle, result),
            RepositoryCompletion::ChangesFailed { title, message } => {
                self.changes_operation_failed(title, &message)
            }
        }
    }

    fn apply_frontend_completion(&self, completion: FrontendCompletion) {
        match completion {
            FrontendCompletion::Repository(completion) => {
                self.apply_repository_completion(completion)
            }
            FrontendCompletion::Agent(event) => self.apply_native_agent_event(event),
            FrontendCompletion::WorkspaceEntries { entries, preferred } => {
                self.apply_workspace_entries(entries, preferred)
            }
            FrontendCompletion::WorkspaceDiscoveryFailed(message) => {
                self.ivars().workspace_discovery_loading.set(false);
                self.refresh_workspace_results("");
                self.refresh_workspace_loading_indicators();
                let alert = NSAlert::new(self.mtm());
                alert.setMessageText(&NSString::from_str("Unable to Load Workspaces"));
                alert.setInformativeText(&NSString::from_str(&message));
                alert.addButtonWithTitle(&NSString::from_str("OK"));
                if let Some(window) = self.ivars().window.get() {
                    alert.beginSheetModalForWindow_completionHandler(window, None);
                }
            }
            FrontendCompletion::WorkspaceMetadata {
                workspace_id,
                generation,
                result,
            } => self.apply_workspace_metadata(&workspace_id, generation, result),
            FrontendCompletion::OpenWorkspace(UiEffectResult::PathsChosen(paths)) => {
                if let Some(path) = paths.into_iter().next() {
                    self.activate_local_workspace(path.to_string_lossy().into_owned());
                }
            }
            FrontendCompletion::OpenWorkspace(UiEffectResult::Cancelled) => {}
            FrontendCompletion::OpenWorkspace(UiEffectResult::Failed(message)) => {
                let alert = NSAlert::new(self.mtm());
                alert.setMessageText(&NSString::from_str("Unable to Open Workspace"));
                alert.setInformativeText(&NSString::from_str(&message));
                alert.addButtonWithTitle(&NSString::from_str("OK"));
                if let Some(window) = self.ivars().window.get() {
                    alert.beginSheetModalForWindow_completionHandler(window, None);
                }
            }
            FrontendCompletion::OpenWorkspace(result) => {
                log::warn!("workspace picker returned unexpected result={result:?}");
            }
            FrontendCompletion::ConfirmDiscard {
                paths,
                result: UiEffectResult::Confirmed(true),
            } => {
                let Some(workspace_id) = self.ivars().active_workspace_id.borrow().clone() else {
                    return;
                };
                let Some(handle) = self.ivars().git_handle.borrow().clone() else {
                    return;
                };
                let Some(requests) = self.ivars().repository_requests.get() else {
                    return;
                };
                self.set_changes_operation_progress("Discarding changes…");
                if let Err(error) = requests.try_send(RepositoryRequest::Discard {
                    workspace_id,
                    handle,
                    paths,
                }) {
                    self.changes_operation_failed(
                        "Discard Failed",
                        &format!("Discard request could not be queued: {error}"),
                    );
                }
            }
            FrontendCompletion::ConfirmDiscard {
                result: UiEffectResult::Confirmed(false) | UiEffectResult::Cancelled,
                ..
            } => {}
            FrontendCompletion::ConfirmDiscard { result, .. } => {
                log::warn!("discard confirmation returned unexpected result={result:?}");
            }
            FrontendCompletion::TerminalRemoteImages {
                workspace_id,
                session_id,
                result,
            } => self.apply_terminal_remote_images(&workspace_id, session_id, result),
            FrontendCompletion::Shutdown => {}
        }
    }

    fn activate_local_workspace(&self, path: String) {
        let workspace = craic_config::ConfiguredWorkspace::local(path);
        let entry = WorkspaceEntry {
            label: workspace.label(),
            workspace,
        };
        let selection_id = entry.selection_id();
        let mut workspaces = self.ivars().workspaces.borrow_mut();
        let inserted = if !workspaces
            .iter()
            .any(|candidate| candidate.selection_id() == selection_id)
        {
            workspaces.push(entry.clone());
            workspaces.sort_by_key(|candidate| candidate.label.to_lowercase());
            true
        } else {
            false
        };
        drop(workspaces);
        if inserted {
            self.queue_workspace_metadata(vec![entry.clone()]);
        }
        self.apply_workspace_button_appearance(&entry);
        self.refresh_workspace_results("");

        let Some(handle) = self.ivars().app_handle.get() else {
            log::warn!("workspace activation ignored because application actor is unavailable");
            return;
        };
        let selection = WorkspaceSelection {
            id: WorkspaceId::new(selection_id),
        };
        if let Err(command) = handle.try_send(AppCommand::SelectWorkspace(selection)) {
            log::warn!("workspace activation queue rejected command={command:?}");
            return;
        }
        self.begin_workspace_transition(&entry.selection_id());
        self.request_repository_load(entry.workspace.clone());
        self.queue_save_last_workspace(entry.workspace);
    }

    fn set_workspace_button_loading(&self, loading: bool) {
        let Some(spinner) = self.ivars().workspace_button_spinner.get() else {
            return;
        };
        if loading {
            if let Some(button) = self.ivars().workspace_button.get() {
                button.setImage(None);
                button.setToolTip(Some(&NSString::from_str("Loading workspace metadata…")));
            }
            unsafe { spinner.startAnimation(None) };
        } else {
            unsafe { spinner.stopAnimation(None) };
        }
    }

    fn refresh_workspace_loading_indicators(&self) {
        let active = self
            .ivars()
            .active_workspace_id
            .borrow()
            .as_deref()
            .and_then(|workspace_id| {
                self.ivars()
                    .workspaces
                    .borrow()
                    .iter()
                    .find(|workspace| workspace.selection_id() == workspace_id)
                    .cloned()
            });
        if let Some(workspace) = active.as_ref() {
            self.apply_workspace_button_appearance(workspace);
        } else {
            let loading = self.ivars().workspace_discovery_loading.get();
            if let Some(button) = self.ivars().workspace_button.get() {
                button.setTitle(&NSString::from_str("Workspace"));
                button.setContentTintColor(None);
                button.setToolTip(Some(&NSString::from_str("Choose workspace")));
                if !loading
                    && let Some(image) = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                        &NSString::from_str("folder"),
                        Some(&NSString::from_str("Workspace")),
                    )
                {
                    button.setImage(Some(&image));
                }
            }
            self.set_workspace_button_loading(loading);
        }
        if let Some(table) = self.ivars().workspace_table.get() {
            table.reloadData();
        }
    }

    fn apply_workspace_button_appearance(&self, workspace: &WorkspaceEntry) {
        let Some(button) = self.ivars().workspace_button.get() else {
            return;
        };
        let metadata = self
            .ivars()
            .workspace_metadata
            .borrow()
            .get(&workspace.selection_id())
            .cloned();
        let title = metadata
            .as_ref()
            .and_then(|metadata| metadata.remote_label.as_deref())
            .unwrap_or(&workspace.label);
        button.setTitle(&NSString::from_str(title));
        let symbol = metadata
            .as_ref()
            .map(|metadata| native_workspace_metadata_symbol(metadata.kind))
            .unwrap_or("folder");
        let description = metadata
            .as_ref()
            .map(|metadata| native_workspace_metadata_description(metadata.kind))
            .unwrap_or("Workspace");
        if let Some(image) = NSImage::imageWithSystemSymbolName_accessibilityDescription(
            &NSString::from_str(symbol),
            Some(&NSString::from_str(description)),
        ) {
            button.setImage(Some(&image));
        }
        button.setContentTintColor(
            workspace
                .workspace
                .color
                .as_ref()
                .and_then(|color| ns_color_from_hex(&color.background))
                .as_deref(),
        );
        button.setToolTip(Some(&NSString::from_str(&format!(
            "Choose workspace — {description}: {}",
            workspace.workspace.path
        ))));
        let loading = self.ivars().workspace_discovery_loading.get()
            || self
                .ivars()
                .workspace_metadata_pending
                .borrow()
                .contains(&workspace.selection_id());
        self.set_workspace_button_loading(loading);
    }

    fn set_page_badge(&self, page_id: &str, badge: NativePageBadge) {
        let Some(group) = self.ivars().page_switcher.get() else {
            return;
        };
        let Some(index) = PAGE_DESCRIPTORS
            .iter()
            .position(|descriptor| descriptor.id == page_id)
        else {
            return;
        };
        let item = group.subitems().objectAtIndex(index);
        if AnyClass::get(c"NSItemBadge").is_none() || !item.respondsToSelector(sel!(setBadge:)) {
            return;
        }
        let badge = match badge {
            NativePageBadge::None | NativePageBadge::Count(0) => None,
            NativePageBadge::Count(count) => Some(NSItemBadge::badgeWithCount(
                count.min(isize::MAX as usize) as isize,
            )),
            NativePageBadge::Indicator => Some(NSItemBadge::indicatorBadge()),
        };
        item.setBadge(badge.as_deref());
    }

    fn restore_changes_page_badge(&self) {
        let count = self
            .ivars()
            .repository_snapshot
            .borrow()
            .as_ref()
            .map(|snapshot| snapshot.changed_files.len())
            .unwrap_or(0);
        self.set_page_badge("changes", NativePageBadge::Count(count));
    }

    fn make_toolbar_item(
        &self,
        identifier: &NSToolbarItemIdentifier,
        will_be_inserted: bool,
    ) -> Option<Retained<NSToolbarItem>> {
        let mtm = self.mtm();
        let identifier_string = identifier.to_string();

        if identifier_string == TOOLBAR_PAGES {
            let mut images = Vec::with_capacity(PAGE_DESCRIPTORS.len());
            let mut labels = Vec::with_capacity(PAGE_DESCRIPTORS.len());
            for page in PAGE_DESCRIPTORS {
                let symbol = match page.id {
                    "changes" => "arrow.triangle.branch",
                    "history" => "clock.arrow.circlepath",
                    "files" => "folder",
                    "containers" => "shippingbox",
                    "agents" => "sparkles",
                    _ => "circle",
                };
                images.push(NSImage::imageWithSystemSymbolName_accessibilityDescription(
                    &NSString::from_str(symbol),
                    Some(&NSString::from_str(page.label)),
                )?);
                labels.push(NSString::from_str(page.label));
            }
            let images = NSArray::from_retained_slice(&images);
            let labels = NSArray::from_retained_slice(&labels);
            // This is Apple's documented image-based toolbar-group initializer. Keeping the
            // control as an NSToolbarItemGroup lets NSToolbar own its single glass surface.
            let pages = unsafe {
                NSToolbarItemGroup::groupWithItemIdentifier_images_selectionMode_labels_target_action(
                    identifier,
                    &images,
                    NSToolbarItemGroupSelectionMode::SelectOne,
                    Some(&labels),
                    Some(self),
                    Some(sel!(selectPage:)),
                    mtm,
                )
            };
            pages.setControlRepresentation(NSToolbarItemGroupControlRepresentation::Expanded);
            pages.setVisibilityPriority(NSToolbarItemVisibilityPriorityUser);
            pages.setLabel(&NSString::from_str("Pages"));
            pages.setPaletteLabel(&NSString::from_str("Pages"));
            pages.setSelectedIndex(0);
            for (index, page) in PAGE_DESCRIPTORS.iter().enumerate() {
                pages
                    .subitems()
                    .objectAtIndex(index)
                    .setToolTip(Some(&NSString::from_str(page.label)));
            }
            if will_be_inserted && self.ivars().page_switcher.get().is_none() {
                let _ = self.ivars().page_switcher.set(pages.retain());
                self.restore_changes_page_badge();
            }
            return Some(pages.into_super());
        }

        if identifier_string == TOOLBAR_ADD_ACTION {
            let group = NSToolbarItemGroup::initWithItemIdentifier(
                NSToolbarItemGroup::alloc(mtm),
                identifier,
            );
            group.setLabel(&NSString::from_str("Quick Actions"));
            group.setPaletteLabel(&NSString::from_str("Quick Actions"));
            group.setControlRepresentation(NSToolbarItemGroupControlRepresentation::Automatic);
            if will_be_inserted && self.ivars().quick_action_group.get().is_none() {
                let _ = self.ivars().quick_action_group.set(group.retain());
                self.configure_native_quick_action_group();
            }
            return Some(group.into_super());
        }

        let item = NSToolbarItem::initWithItemIdentifier(NSToolbarItem::alloc(mtm), identifier);

        match identifier_string.as_str() {
            TOOLBAR_WORKSPACE => {
                let active_workspace = self
                    .ivars()
                    .active_workspace_id
                    .borrow()
                    .as_deref()
                    .and_then(|workspace_id| {
                        self.ivars()
                            .workspaces
                            .borrow()
                            .iter()
                            .find(|candidate| candidate.selection_id() == workspace_id)
                            .cloned()
                    });
                let workspace_title = active_workspace
                    .as_ref()
                    .map(|workspace| workspace.label.clone())
                    .unwrap_or_else(|| "Workspace".to_string());
                let workspace_image = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                    &NSString::from_str("folder"),
                    Some(&NSString::from_str("Workspace")),
                )?;
                let workspace = unsafe {
                    NSButton::buttonWithTitle_image_target_action(
                        &NSString::from_str(&workspace_title),
                        &workspace_image,
                        Some(self),
                        Some(sel!(toggleWorkspacePicker:)),
                        mtm,
                    )
                };
                workspace.setBezelStyle(NSBezelStyle::Toolbar);
                workspace.setControlSize(NSControlSize::Regular);
                workspace.setFont(Some(&NSFont::systemFontOfSize(13.0)));
                workspace.setImagePosition(NSCellImagePosition::ImageLeading);
                workspace.setImageHugsTitle(true);
                workspace.setLineBreakMode(NSLineBreakMode::ByTruncatingMiddle);
                workspace.setTranslatesAutoresizingMaskIntoConstraints(false);
                workspace.setContentCompressionResistancePriority_forOrientation(
                    NSLayoutPriorityDefaultLow,
                    NSLayoutConstraintOrientation::Horizontal,
                );
                workspace
                    .widthAnchor()
                    .constraintGreaterThanOrEqualToConstant(TOOLBAR_WORKSPACE_MIN_WIDTH)
                    .setActive(true);
                workspace
                    .widthAnchor()
                    .constraintLessThanOrEqualToConstant(TOOLBAR_WORKSPACE_MAX_WIDTH)
                    .setActive(true);
                workspace.setToolTip(Some(&NSString::from_str("Choose workspace")));
                workspace.setContentTintColor(
                    active_workspace
                        .as_ref()
                        .and_then(|workspace| workspace.workspace.color.as_ref())
                        .and_then(|color| ns_color_from_hex(&color.background))
                        .as_deref(),
                );
                let spinner = NSProgressIndicator::initWithFrame(
                    NSProgressIndicator::alloc(mtm),
                    NSRect::new(NSPoint::new(0.0, 0.0), NSSize::new(16.0, 16.0)),
                );
                spinner.setStyle(NSProgressIndicatorStyle::Spinning);
                spinner.setControlSize(NSControlSize::Small);
                spinner.setIndeterminate(true);
                spinner.setDisplayedWhenStopped(false);
                spinner.setTranslatesAutoresizingMaskIntoConstraints(false);
                workspace.addSubview(&spinner);
                spinner
                    .centerYAnchor()
                    .constraintEqualToAnchor(&workspace.centerYAnchor())
                    .setActive(true);
                spinner
                    .leadingAnchor()
                    .constraintEqualToAnchor_constant(&workspace.leadingAnchor(), 10.0)
                    .setActive(true);
                spinner
                    .widthAnchor()
                    .constraintEqualToConstant(16.0)
                    .setActive(true);
                spinner
                    .heightAnchor()
                    .constraintEqualToConstant(16.0)
                    .setActive(true);
                item.setLabel(&NSString::from_str("Workspace"));
                item.setPaletteLabel(&NSString::from_str("Workspace"));
                item.setVisibilityPriority(NSToolbarItemVisibilityPriorityHigh);
                item.setView(Some(&workspace));
                if will_be_inserted && self.ivars().workspace_button.get().is_none() {
                    let _ = self.ivars().workspace_button.set(workspace);
                    let _ = self.ivars().workspace_button_spinner.set(spinner);
                    self.refresh_workspace_loading_indicators();
                }
            }
            TOOLBAR_BRANCH => {
                let branch_image = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                    &NSString::from_str("arrow.triangle.branch"),
                    Some(&NSString::from_str("Branch")),
                )?;
                // SAFETY: The target implements toggleBranchPicker: with an NSButton sender.
                let branch = unsafe {
                    NSButton::buttonWithTitle_image_target_action(
                        &NSString::from_str("Branch"),
                        &branch_image,
                        Some(self),
                        Some(sel!(toggleBranchPicker:)),
                        mtm,
                    )
                };
                branch.setBezelStyle(NSBezelStyle::Toolbar);
                branch.setControlSize(NSControlSize::Regular);
                branch.setFont(Some(&NSFont::systemFontOfSize(13.0)));
                branch.setImagePosition(NSCellImagePosition::ImageLeading);
                branch.setImageHugsTitle(true);
                branch.setToolTip(Some(&NSString::from_str("Branch")));
                branch.setEnabled(false);
                item.setLabel(&NSString::from_str("Branch"));
                item.setPaletteLabel(&NSString::from_str("Branch"));
                item.setVisibilityPriority(NSToolbarItemVisibilityPriorityLow);
                item.setView(Some(&branch));
                if will_be_inserted && self.ivars().branch_button.get().is_none() {
                    let _ = self.ivars().branch_button.set(branch);
                }
            }
            TOOLBAR_FETCH => {
                let label = NSString::from_str("Fetch remote");
                // The refresh SF Symbol reaches its trailing alignment edge; an en-space keeps
                // the visible title from touching the arrowhead while preserving native sizing.
                let visible_label = NSString::from_str("\u{2002}Fetch remote");
                let image = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                    &NSString::from_str("arrow.triangle.2.circlepath"),
                    Some(&label),
                )?;
                // SAFETY: The target implements fetchRemote: with an NSButton sender.
                let button = unsafe {
                    NSButton::buttonWithTitle_image_target_action(
                        &visible_label,
                        &image,
                        Some(self),
                        Some(sel!(fetchRemote:)),
                        mtm,
                    )
                };
                button.setBezelStyle(NSBezelStyle::Toolbar);
                button.setControlSize(NSControlSize::Regular);
                button.setImagePosition(NSCellImagePosition::ImageLeading);
                button.setImageHugsTitle(true);
                button.setToolTip(Some(&NSString::from_str("Last fetched: unknown")));
                button.setEnabled(false);
                let spinner = NSProgressIndicator::initWithFrame(
                    NSProgressIndicator::alloc(mtm),
                    NSRect::new(NSPoint::new(0.0, 0.0), NSSize::new(16.0, 16.0)),
                );
                spinner.setStyle(NSProgressIndicatorStyle::Spinning);
                spinner.setControlSize(NSControlSize::Small);
                spinner.setIndeterminate(true);
                spinner.setDisplayedWhenStopped(false);
                spinner.setTranslatesAutoresizingMaskIntoConstraints(false);
                button.addSubview(&spinner);
                spinner
                    .centerYAnchor()
                    .constraintEqualToAnchor(&button.centerYAnchor())
                    .setActive(true);
                spinner
                    .leadingAnchor()
                    .constraintEqualToAnchor_constant(&button.leadingAnchor(), 10.0)
                    .setActive(true);
                spinner
                    .widthAnchor()
                    .constraintEqualToConstant(16.0)
                    .setActive(true);
                spinner
                    .heightAnchor()
                    .constraintEqualToConstant(16.0)
                    .setActive(true);
                item.setLabel(&label);
                item.setPaletteLabel(&label);
                item.setVisibilityPriority(NSToolbarItemVisibilityPriorityLow);
                item.setView(Some(&button));
                if will_be_inserted && self.ivars().fetch_button.get().is_none() {
                    let _ = self.ivars().fetch_button.set(button);
                    let _ = self.ivars().fetch_spinner.set(spinner);
                }
            }
            TOOLBAR_TERMINAL => {
                let (label, symbol, tooltip, action, enabled) = (
                    "Terminal",
                    "apple.terminal",
                    "Show terminal",
                    sel!(toggleTerminal:),
                    true,
                );
                let image = NSImage::imageWithSystemSymbolName_accessibilityDescription(
                    &NSString::from_str(symbol),
                    Some(&NSString::from_str(label)),
                )
                .or_else(|| {
                    NSImage::imageWithSystemSymbolName_accessibilityDescription(
                        &NSString::from_str("terminal"),
                        Some(&NSString::from_str(label)),
                    )
                })?;
                item.setLabel(&NSString::from_str(label));
                item.setPaletteLabel(&NSString::from_str(label));
                item.setToolTip(Some(&NSString::from_str(tooltip)));
                item.setImage(Some(&image));
                item.setBordered(true);
                item.setEnabled(enabled);
                unsafe {
                    item.setTarget(Some(self));
                    item.setAction(Some(action));
                }
                if will_be_inserted && self.ivars().terminal_toolbar_item.get().is_none() {
                    let _ = self.ivars().terminal_toolbar_item.set(item.clone());
                }
            }
            _ => return None,
        }
        Some(item)
    }

